-- ============================================================================
-- 052: fusion de las rutas Web3 Basica y Trading Basico
-- ============================================================================
-- ESTADO: APLICADA EN PRODUCCION EL 2026-09-25.
--   Ejecutada por PostgREST y versionada despues, como la 048.
--
-- QUE HACE
--   Cada ruta pasa de dos cursos a uno:
--     "Introduccion a Web3"    absorbe "Ecosistema Web3 explicado"
--     "Introduccion al trading" absorbe "Gestion del riesgo y mentalidad"
--   Los dos pasan de 2 modulos / 6 lecciones a 3 / 9, con quiz de 27 preguntas
--   (9 por modulo, todas con explicacion), y cambian de titulo.
--
--   Los slugs de los cursos NO cambian, para conservar sus fichas. El titulo
--   "Que es Web3 y que no" sobre el slug introduccion-a-web3 es una
--   discordancia aceptada a cambio de no redirigir dos fichas mas.
--
-- POR QUE
--   Diagnostico del 24/09/2026. Los cuatro cursos tenian ~1.000 caracteres por
--   leccion, menos que UNA de las lecciones escritas esta semana. Los dos de
--   trading se solapaban como los de custodia: "errores-comunes-en-trading" y
--   "por-que-la-mayoria-pierde-dinero" eran practicamente la misma leccion.
--
--   Y los de trading tenian tres juicios que chocan con el Principio #1:
--   "el tiempo es aliado del inversor", "la consistencia precede a la
--   rentabilidad" y "ganar dinero es una consecuencia". Ademas de un armazon
--   operativo -stops, tamano de posicion, checklist- que el curso nuevo no
--   tiene: responde a si operar, nunca a como.
--
-- QUE CONSERVA
--   Las 12 lecciones que ya existian conservan su id, y con el sus filas de
--   user_progress. Se crean 6 lecciones y 2 modulos.
--   Los 4 intentos de quiz previos: quiz_attempts no tiene clave ajena contra
--   quiz_questions.
--   Los 9 certificados de los cuatro cursos, y todos los completed_at.
--
-- QUE NO TOCA, A PROPOSITO
--   Los certificados de enero de "Gestion del riesgo" emitidos sobre
--   matriculas al 100% con 3 de 6 lecciones hechas (decision del 24/09/2026:
--   se quedan como estan). Al archivarse el curso dejan de mostrar porcentaje.
--
-- OJO CON EL DISPARADOR DE LA 030
--   Cambiar title, description y long_description devuelve un curso publicado
--   a 'pending_review'. El bloque 6 lo corrige, como en la 048. Regla 22.
--
-- RESPALDO
--   C:/Users/alber/backups-sql/052-volver-atras.sql.bak (filas completas, con
--   slug). No restaura lo creado: los ids estan al final de este fichero.
-- ============================================================================

BEGIN;

SET LOCAL app.skip_republish_check = 'on';

-- ============================================================================
-- 1. Textos de las dos rutas
-- ============================================================================

UPDATE public.learning_paths SET
  subtitle = 'Entender antes de usar',
  short_description = 'Qué propone Web3, qué cuesta y qué parte está realmente descentralizada. Con criterio para evaluar un proyecto antes de tocarlo.',
  long_description = 'Web3 se cuenta casi siempre desde un bando. Esta ruta describe: qué sustituye por qué, qué se paga a cambio y qué condiciones tienen que cumplirse para que el resultado sea el prometido.

Recorre las piezas —la clave con la que entras, el contrato que firmas, el token que recibes— y termina con un método para mirar un proyecto concreto. No sirve para saber si algo va a funcionar: sirve para saber de qué depende.'
 WHERE slug = 'web3-basica';

UPDATE public.learning_paths SET
  subtitle = 'Decidir antes de operar',
  short_description = 'Qué es operar, de dónde sale el dinero que gana un operador y por qué casi nadie gana. Para decidir si te interesa, no para aprender a hacerlo.',
  long_description = 'Esta ruta no enseña a operar, y lo dice desde la primera lección: no hay estrategias ni indicadores, porque esas decisiones dependen de tu situación.

Responde a otras dos preguntas. Qué es exactamente esta actividad, y por qué casi nadie gana dinero con ella: de dónde sale el beneficio, qué costes mueven el punto de equilibrio, qué hace el apalancamiento y qué ocurre en la cabeza cuando hay dinero propio delante. Termina con lo necesario para decidir, incluidas las obligaciones fiscales.

El trading no es una estafa ni una oportunidad. Es una actividad con unas probabilidades concretas, y la decisión es tuya.'
 WHERE slug = 'trading-basico';

-- ============================================================================
-- 2. Qué es Web3 y qué no
-- ============================================================================

UPDATE public.courses SET
  title = 'Qué es Web3 y qué no',
  description = 'Entiende qué propone Web3, qué cuesta y qué parte está realmente descentralizada. Con criterio para evaluar cualquier proyecto.',
  long_description = 'Web3 se explica casi siempre desde uno de dos bandos: el que promete que lo cambiará todo y el que asegura que es humo. Este curso no hace ninguna de las dos cosas.

Describe qué propone exactamente —qué sustituye por qué—, qué cuesta esa sustitución, y qué condiciones tienen que cumplirse para que el resultado sea el prometido. Después recorre las piezas: la clave con la que entras, el contrato que firmas y el token que recibes, con lo que cada una puede hacer y lo que no.

Termina con un método para mirar un proyecto concreto antes de tocarlo. No sirve para saber si algo va a funcionar, sino para saber de qué depende, que es lo que permite decidir con criterio.

No hace falta saber programar. Sí ayuda haber visto antes cómo funciona una red como Bitcoin.',
  total_modules = 3, total_lessons = 9
 WHERE slug = 'introduccion-a-web3';

-- M1 De dónde viene la idea
UPDATE public.modules SET title = 'De dónde viene la idea', slug = 'de-donde-viene-la-idea',
  description = 'Cómo funciona el modelo actual de internet, qué propone Web3 exactamente y qué ha cambiado de verdad frente a lo que sigue igual.', order_index = 0
 WHERE id = '9924b7da-e61a-47d2-8e25-f0f9c5e2ea76';

-- M2 Las piezas
UPDATE public.modules SET title = 'Las piezas', slug = 'las-piezas-de-web3',
  description = 'La clave, el contrato y el token: qué es cada uno, qué puede hacer, qué no garantiza y dónde está el riesgo.', order_index = 1
 WHERE id = '2a79ef13-08d6-4e68-9d6b-67a0f505fe78';

