VALUES ('4a17850e-b3b2-48f2-9368-fb88bbcf3705', 'd7cb7b7d-47b9-4344-bbe0-9eabe4a36d48', 'Criterio', 'criterio-para-evaluar-web3', 'Dónde aporta algo un registro compartido y dónde es una base de datos cara, y cómo mirar un proyecto antes de tocarlo.', 2, FALSE)
