  slug = EXCLUDED.slug, description = EXCLUDED.description, order_index = EXCLUDED.order_index,
  content = EXCLUDED.content;

DELETE FROM public.quiz_questions WHERE module_id IN ('9924b7da-e61a-47d2-8e25-f0f9c5e2ea76', '2a79ef13-08d6-4e68-9d6b-67a0f505fe78', '4a17850e-b3b2-48f2-9368-fb88bbcf3705');

-- quiz M1
INSERT INTO public.quiz_questions (module_id, question, explanation, options, correct_answer, order_index, difficulty, points)
VALUES ('9924b7da-e61a-47d2-8e25-f0f9c5e2ea76', '¿Por qué se impuso el modelo de plataforma en internet?', 'El orden de los hechos importa: el modelo no se diseñó para concentrar poder, se diseñó para que las cosas funcionaran a la primera entre millones de desconocidos. La concentración vino con él.', '["Porque las empresas se coordinaron para repartirse el mercado","Porque resolvía un problema real: que millones de personas pudieran interactuar sin que nada fallara","Porque la tecnología descentralizada no existía todavía","Porque los usuarios pidieron ceder el control de sus datos"]'::jsonb, 1, 1, 'medium', 1);
INSERT INTO public.quiz_questions (module_id, question, explanation, options, correct_answer, order_index, difficulty, points)
VALUES ('9924b7da-e61a-47d2-8e25-f0f9c5e2ea76', 'De los trabajos que hace una plataforma, ¿cuál explica que sea rápida y barata?', 'La operación se confirma en el acto porque la anota una sola entidad en su propia base de datos, sin ponerse de acuerdo con nadie. No es un defecto del diseño: es el diseño, y es exactamente lo que se paga al quitarla.', '["Que guarde copias de seguridad","Que filtre el contenido abusivo","Que confirme al instante, porque decide una sola entidad","Que te devuelva el acceso si pierdes la contraseña"]'::jsonb, 2, 2, 'medium', 1);
INSERT INTO public.quiz_questions (module_id, question, explanation, options, correct_answer, order_index, difficulty, points)
VALUES ('9924b7da-e61a-47d2-8e25-f0f9c5e2ea76', 'Se dice que lo que parece gratis se paga con atención y perfilado. ¿Qué tiene eso de particular?', 'No está oculto —está en las condiciones y es el negocio declarado— pero es un precio que no ves y que no puedes comparar. No hay una cifra al lado del botón, así que no hay forma de decidir si te compensa.', '["Que es un secreto que las empresas ocultan deliberadamente","Que es ilegal en la mayoría de los países","Que es un precio que no se ve y no se puede comparar con ninguna alternativa","Que solo afecta a quienes usan redes sociales"]'::jsonb, 2, 3, 'medium', 1);
INSERT INTO public.quiz_questions (module_id, question, explanation, options, correct_answer, order_index, difficulty, points)
VALUES ('9924b7da-e61a-47d2-8e25-f0f9c5e2ea76', '¿Qué hace falta para perder una cuenta y lo que construiste en ella?', 'Ni mala fe ni catástrofe: basta con que quien decide sea otro. Las condiciones las cambia una sola de las partes, y ese es el trato desde el principio. Además, la reputación y los seguidores no se pueden descargar.', '["Basta con que quien decide sea otro: una decisión automática, un error o una norma nueva","Que la empresa actúe de mala fe deliberadamente","Que incumplas la ley del país donde vives","Que dejes de usar el servicio durante mucho tiempo"]'::jsonb, 0, 4, 'medium', 1);
INSERT INTO public.quiz_questions (module_id, question, explanation, options, correct_answer, order_index, difficulty, points)
VALUES ('9924b7da-e61a-47d2-8e25-f0f9c5e2ea76', 'Web3 sustituye tres piezas. ¿Cuáles son?', 'Debajo de toda la terminología hay un cambio único: donde antes decidía una entidad, ahora tienen que coincidir muchas copias independientes. Aplicado a la cuenta, al servidor y al contrato.', '["El navegador, el servidor y el protocolo","La cuenta pasa a clave, el servidor a registro compartido y el contrato a código que se ejecuta solo","El dinero, el banco y la ley","La identidad, la privacidad y la seguridad"]'::jsonb, 1, 5, 'medium', 1);
INSERT INTO public.quiz_questions (module_id, question, explanation, options, correct_answer, order_index, difficulty, points)
VALUES ('9924b7da-e61a-47d2-8e25-f0f9c5e2ea76', 'Se dice que lo que gana Web3 se enuncia en negativo. ¿Qué significa eso?', 'Nadie puede cerrarte el acceso, cambiar las reglas a mitad ni retener lo tuyo. Todo son cosas que no pueden pasar: no añade capacidades nuevas al usuario, retira la capacidad de un tercero de intervenir.', '["Que sus ventajas son difíciles de demostrar","Que la mayoría de los proyectos fracasan","Que no añade capacidades al usuario: retira la capacidad de un tercero de intervenir","Que solo sirve para evitar impuestos"]'::jsonb, 2, 6, 'medium', 1);
INSERT INTO public.quiz_questions (module_id, question, explanation, options, correct_answer, order_index, difficulty, points)
VALUES ('9924b7da-e61a-47d2-8e25-f0f9c5e2ea76', 'Los costes de Web3 —más lento, más caro, irreversible— ¿son fallos pendientes de arreglo?', 'Son la otra cara de lo que se gana: la velocidad y el bajo coste del modelo anterior venían de que decidía una sola entidad. Al quitarla, se paga exactamente ahí. Quien prometa las ventajas sin los costes describe algo que no existe.', '["Sí, se resolverán cuando la tecnología madure","No: son la otra cara de lo que se gana al quitar a la entidad que decidía","Sí, ya están resueltos en las redes modernas","No, porque en realidad no existen esos costes"]'::jsonb, 1, 7, 'medium', 1);
INSERT INTO public.quiz_questions (module_id, question, explanation, options, correct_answer, order_index, difficulty, points)
VALUES ('9924b7da-e61a-47d2-8e25-f0f9c5e2ea76', 'De las cuatro condiciones que tienen que cumplirse para que Web3 funcione como promete, ¿cuál es la más olvidada?', 'La mayoría de la gente no habla con el registro directamente: usa una web o una aplicación que consulta por ella, y esas piezas suelen estar alojadas donde todo lo demás. Se puede ser descentralizado por dentro y llegar por una puerta que controla una sola empresa.', '["Que haya bastantes participantes independientes","Que el código no tenga llaves de administración ocultas","Que tú custodies la clave","Que puedas llegar al sistema sin pedir permiso a nadie"]'::jsonb, 3, 8, 'medium', 1);
INSERT INTO public.quiz_questions (module_id, question, explanation, options, correct_answer, order_index, difficulty, points)
VALUES ('9924b7da-e61a-47d2-8e25-f0f9c5e2ea76', 'En muchos proyectos se vota en proporción a cuántas unidades se tienen. ¿Qué es eso?', 'Quien reunió más al principio decide. Es un mecanismo distinto de concentración, no su ausencia. Y si el reparto inicial fue desigual, cualquier mecanismo posterior basado en cuánto tienes lo reproduce.', '["La forma más justa de gobernanza descentralizada","Otro mecanismo de concentración, no su ausencia","Una garantía de que las decisiones son técnicas y no políticas","Un sistema equivalente a una persona, un voto"]'::jsonb, 1, 9, 'medium', 1);

-- quiz M2
INSERT INTO public.quiz_questions (module_id, question, explanation, options, correct_answer, order_index, difficulty, points)
VALUES ('2a79ef13-08d6-4e68-9d6b-67a0f505fe78', '¿Qué distingue a una clave de una cuenta?', 'Una cuenta la crea un servicio y deja de existir si ese servicio la borra. Una clave se genera al azar en tu dispositivo y ya existe, con o sin aplicaciones que la reconozcan. Por eso vale en todas partes y nadie puede revocarla.', '["Que la clave es más larga y difícil de adivinar","Que la clave no la emite nadie: existe por sí misma y nadie puede revocarla","Que la clave se puede recuperar desde el correo","Que la cuenta es gratuita y la clave se compra"]'::jsonb, 1, 1, 'medium', 1);
INSERT INTO public.quiz_questions (module_id, question, explanation, options, correct_answer, order_index, difficulty, points)
VALUES ('2a79ef13-08d6-4e68-9d6b-67a0f505fe78', '¿Para qué NO sirve una clave como identidad?', 'Una clave no dice nada sobre ti: solo acredita que quien firma controla ese número. Para cualquier cosa que exija saber quién eres de verdad hace falta que alguien de fuera lo certifique, y ahí reaparece el tercero de confianza.', '["Para demostrar que eres el mismo que la vez anterior","Para demostrar que tienes algo concreto","Para abrir una cuenta regulada o demostrar tu edad","Para participar sin dar tus datos personales"]'::jsonb, 2, 2, 'medium', 1);
INSERT INTO public.quiz_questions (module_id, question, explanation, options, correct_answer, order_index, difficulty, points)
VALUES ('2a79ef13-08d6-4e68-9d6b-67a0f505fe78', 'Usas siempre la misma clave y un día alguien la conecta con tu nombre. ¿Qué ocurre?', 'El registro es público y permanente, y todo lo hecho con esa clave queda enlazado. Basta un punto de conexión —una compra, una plataforma que te identificó— para que el historial entero deje de ser anónimo, hacia atrás y hacia delante. No hay forma de deshacerlo.', '["Solo queda expuesto lo que hagas a partir de ese momento","Queda expuesto el historial entero, hacia atrás y hacia delante","No pasa nada: las direcciones no llevan nombre","Puedes borrar el historial asociado a esa dirección"]'::jsonb, 1, 3, 'medium', 1);
INSERT INTO public.quiz_questions (module_id, question, explanation, options, correct_answer, order_index, difficulty, points)
VALUES ('2a79ef13-08d6-4e68-9d6b-67a0f505fe78', '¿Por qué un contrato inteligente no es inteligente ni es un contrato?', 'No interpreta, no juzga y no entiende el contexto: es un programa con instrucciones fijas que hace lo mismo cada vez, y si tienen un fallo lo ejecuta con toda fidelidad. Y no hay tribunal que pueda interpretarlo cuando hay discrepancia.', '["Porque lo escribe una persona y no una máquina","Porque no interpreta nada y no hay a quién acudir si hay discrepancia","Porque todavía es una tecnología experimental","Porque necesita que alguien lo ejecute manualmente"]'::jsonb, 1, 4, 'medium', 1);
INSERT INTO public.quiz_questions (module_id, question, explanation, options, correct_answer, order_index, difficulty, points)
VALUES ('2a79ef13-08d6-4e68-9d6b-67a0f505fe78', 'Ante un contrato inteligente, ¿cuál es la pregunta correcta?', 'Muchos contratos conservan una función que permite a una dirección pausarlos, actualizarlos o vaciarlos, a veces por buenas razones. Si alguien puede cambiar las reglas hay un tercero de confianza, aunque no aparezca en ninguna pantalla.', '["¿Es inmutable?","¿Cuánto lleva funcionando?","¿Quién puede cambiarlo, y qué hace falta para que lo cambie?","¿Cuántas personas lo usan?"]'::jsonb, 2, 5, 'medium', 1);
INSERT INTO public.quiz_questions (module_id, question, explanation, options, correct_answer, order_index, difficulty, points)
VALUES ('2a79ef13-08d6-4e68-9d6b-67a0f505fe78', 'Una aplicación te pide firmar una autorización. ¿Qué estás concediendo?', 'Das a un contrato permiso para mover cierto tipo de unidades de tu dirección cuando él decida, sin volver a preguntarte. Suele pedirse sin límite de cantidad y no caduca: sigue vigente meses después, cuando ya no la recuerdas.', '["Permiso para una operación concreta, esta vez","Permiso para que un contrato mueva tus fondos cuando quiera, normalmente sin límite y sin caducidad","Permiso para que la aplicación lea tu historial","Permiso para iniciar sesión, sin más consecuencias"]'::jsonb, 1, 6, 'medium', 1);
INSERT INTO public.quiz_questions (module_id, question, explanation, options, correct_answer, order_index, difficulty, points)
VALUES ('2a79ef13-08d6-4e68-9d6b-67a0f505fe78', 'El ataque más rentable contra una aplicación descentralizada no toca el contrato. ¿En qué consiste?', 'Una aplicación es contratos más una web corriente, alojada donde se aloja todo. Alterar esa web —o construir una copia idéntica— hace que el botón de siempre proponga una firma distinta. El contrato es honesto; lo que cambió fue lo que te pidieron firmar.', '["En adivinar la clave privada del usuario","En alterar la web, o copiarla, para que proponga una firma distinta","En modificar el registro compartido","En saturar la red para que las operaciones fallen"]'::jsonb, 1, 7, 'medium', 1);
INSERT INTO public.quiz_questions (module_id, question, explanation, options, correct_answer, order_index, difficulty, points)
VALUES ('2a79ef13-08d6-4e68-9d6b-67a0f505fe78', '¿Qué es exactamente un token?', 'Una fila en la tabla de un contrato que dice que cierta dirección tiene cierta cantidad de algo. No hay un objeto ni una moneda en ningún sitio. Crearlo no cuesta casi nada, y su existencia no acredita quién lo hizo ni si alguien lo respalda.', '["Un archivo cifrado que guardas en tu dispositivo","Una fila en la tabla de un contrato: una dirección y una cantidad","Una moneda digital emitida por un banco central","Un certificado de propiedad reconocido legalmente"]'::jsonb, 1, 8, 'medium', 1);
INSERT INTO public.quiz_questions (module_id, question, explanation, options, correct_answer, order_index, difficulty, points)
VALUES ('2a79ef13-08d6-4e68-9d6b-67a0f505fe78', 'Compras un NFT de una ilustración. ¿Qué has adquirido?', 'La imagen casi nunca está dentro del registro: lo anotado es una dirección donde encontrarla, y si el archivo desaparece la anotación apunta a nada. Salvo declaración expresa del creador, tampoco compras derechos sobre la obra. Único es una propiedad del registro; el valor depende de lo que haya detrás.', '["La propiedad intelectual de la ilustración","El archivo original, guardado en el registro compartido","La anotación de que una unidad concreta está a tu nombre","La exclusividad: nadie más puede tener esa imagen"]'::jsonb, 2, 9, 'medium', 1);

-- quiz M3
INSERT INTO public.quiz_questions (module_id, question, explanation, options, correct_answer, order_index, difficulty, points)
VALUES ('4a17850e-b3b2-48f2-9368-fb88bbcf3705', '¿Cuál es la prueba para saber si un registro compartido aporta algo?', 'Si no hay nadie con motivo y capacidad para manipular el registro a quien no se pueda obligar, un árbitro es más rápido y más barato. Esta tecnología sirve justamente para cuando no hay un árbitro aceptable.', '["¿Cuántos usuarios tiene el proyecto?","¿Hay alguien con motivo y capacidad para cambiar el registro en su favor, a quien no se pueda obligar?","¿Está el código publicado?","¿Cuánto cuesta cada operación?"]'::jsonb, 1, 1, 'medium', 1);
INSERT INTO public.quiz_questions (module_id, question, explanation, options, correct_answer, order_index, difficulty, points)
VALUES ('4a17850e-b3b2-48f2-9368-fb88bbcf3705', '¿Por qué fracasaron tantos proyectos de «blockchain empresarial»?', 'Eran registros compartidos entre partes que ya se fiaban entre sí, con una empresa manteniendo todas las copias. Toda la complejidad y ninguna de las razones. Si funcionaría igual con una base de datos normal, es una base de datos normal.', '["Porque la tecnología era demasiado lenta para ese uso","Porque repartían el registro entre partes que ya se fiaban entre sí: toda la complejidad sin las razones","Porque los reguladores los prohibieron","Porque faltaban programadores especializados"]'::jsonb, 1, 2, 'medium', 1);
INSERT INTO public.quiz_questions (module_id, question, explanation, options, correct_answer, order_index, difficulty, points)
VALUES ('4a17850e-b3b2-48f2-9368-fb88bbcf3705', 'En la trazabilidad de productos, ¿dónde está el eslabón débil?', 'Si alguien tiene que teclear que la mercancía llegó, el registro garantiza que nadie altere lo tecleado, no que fuera verdad. El eslabón débil es el humano de la entrada, y el registro compartido no lo arregla.', '["En la capacidad del registro para almacenar tantos datos","En quien introduce el dato: el registro protege lo tecleado, no su veracidad","En la velocidad de confirmación de las operaciones","En el coste de cada anotación"]'::jsonb, 1, 3, 'medium', 1);
INSERT INTO public.quiz_questions (module_id, question, explanation, options, correct_answer, order_index, difficulty, points)
VALUES ('4a17850e-b3b2-48f2-9368-fb88bbcf3705', 'Un token representa euros depositados en un banco. ¿Qué garantiza el registro?', 'Cuando el token representa algo que vive fuera del registro, la promesa la hace una entidad concreta. El registro garantiza que tienes el recibo y que circula sin permiso; no garantiza que haya euros detrás ni que te los canjeen.', '["Que existen los euros que respaldan cada token","Que un auditor ha verificado las reservas","Que tienes el recibo, no que haya euros detrás","Que podrás canjearlo en cualquier momento"]'::jsonb, 2, 4, 'medium', 1);
INSERT INTO public.quiz_questions (module_id, question, explanation, options, correct_answer, order_index, difficulty, points)
VALUES ('4a17850e-b3b2-48f2-9368-fb88bbcf3705', 'De las seis cosas que mirar en un proyecto, ¿cuál es la principal?', 'Quién puede cambiar las reglas: nadie, una decisión colectiva con demora, varias firmas repartidas, o una sola dirección. Ninguna opción descalifica por sí sola; lo descalificador es que el proyecto no lo diga, o que diga «descentralizado» cuando es lo último.', '["Quién puede cambiar las reglas de los contratos","Cuántos seguidores tiene en redes sociales","Si el precio ha subido en los últimos meses","Si aparece en medios especializados"]'::jsonb, 0, 5, 'medium', 1);
INSERT INTO public.quiz_questions (module_id, question, explanation, options, correct_answer, order_index, difficulty, points)
VALUES ('4a17850e-b3b2-48f2-9368-fb88bbcf3705', 'El equipo de un proyecto es anónimo. ¿Qué conclusión se puede sacar?', 'El anonimato no descalifica por sí mismo: el sistema más sólido del sector lo creó alguien que desapareció. Lo que importa es la combinación de anonimato, capacidad de cambiar las reglas y custodia de fondos ajenos, que es muy difícil de justificar.', '["Que es una estafa: los proyectos serios dan la cara","Ninguna por sí sola; importa combinado con quién controla las reglas y quién custodia los fondos","Que es más seguro, porque no pueden ser presionados","Que no se puede evaluar el proyecto de ninguna forma"]'::jsonb, 1, 6, 'medium', 1);
INSERT INTO public.quiz_questions (module_id, question, explanation, options, correct_answer, order_index, difficulty, points)
VALUES ('4a17850e-b3b2-48f2-9368-fb88bbcf3705', 'Haces una pregunta técnica sencilla en la comunidad de un proyecto y la pregunta molesta. ¿Qué indica?', 'Es de las señales más fiables que existen y no exige entender nada técnico. Un proyecto sólido agradece las preguntas técnicas; uno que no lo es las trata como deslealtad. Aparece por el mismo motivo en el curso de Seguridad básica.', '["Que la comunidad está saturada de preguntas repetidas","Que ya tienes la respuesta: un proyecto sólido agradece las preguntas técnicas","Que conviene preguntar en privado a un administrador","Nada: es normal en comunidades grandes"]'::jsonb, 1, 7, 'medium', 1);
INSERT INTO public.quiz_questions (module_id, question, explanation, options, correct_answer, order_index, difficulty, points)
VALUES ('4a17850e-b3b2-48f2-9368-fb88bbcf3705', '¿Qué te permite saber el método de evaluación de este curso?', 'Sirve para saber de qué depende lo que miras: qué tendría que fallar y quién tendría que fallar. No dice si algo va a funcionar ni si conviene participar, y el riesgo de aprender a evaluar es creerse a salvo: entender cómo funciona algo y acertar con ello son cosas distintas.', '["Si el proyecto va a tener éxito","Si conviene participar o no","De qué depende: qué y quién tendría que fallar para que salga mal","Cuánto puede subir o bajar su valor"]'::jsonb, 2, 8, 'medium', 1);
INSERT INTO public.quiz_questions (module_id, question, explanation, options, correct_answer, order_index, difficulty, points)
VALUES ('4a17850e-b3b2-48f2-9368-fb88bbcf3705', '¿Qué parte del riesgo no cubre en absoluto el método de este curso?', 'La que ataca el juicio en lugar del sistema: alguien que se gana tu confianza despacio y espera a que preguntes tú no deja ninguna señal técnica que detectar. Está tratado en Seguridad básica, lección 1.2, y es lo que más fondos se lleva.', '["Los fallos de programación de los contratos","La caída de la web por la que entras","El ataque contra el juicio: quien se gana tu confianza despacio","La concentración de la gobernanza"]'::jsonb, 2, 9, 'medium', 1);

-- ============================================================================
-- 3. Trading: qué es y por qué casi nadie gana
-- ============================================================================

UPDATE public.courses SET
  title = 'Trading: qué es y por qué casi nadie gana',
  description = 'Qué es exactamente operar, de dónde sale el dinero que gana un operador y qué hace falta saber para decidir si te interesa.',
  long_description = 'Este curso no enseña a operar. No hay estrategias, ni indicadores, ni cuándo entrar o salir: esas decisiones dependen de tu situación y quien no te conoce no puede tomarlas por ti.

Lo que hace es responder a dos preguntas que casi nadie responde antes de empezar. Qué es exactamente esta actividad y en qué se diferencia de otras que se le parecen. Y por qué casi nadie gana dinero con ella, con los motivos concretos: de dónde sale el beneficio, qué costes mueven el punto de equilibrio, qué hace el apalancamiento y qué ocurre en la cabeza cuando hay dinero propio delante.

Termina con lo necesario para decidir: qué se puede esperar razonablemente, qué obligaciones fiscales aparecen aunque el año sea malo, y para quién tiene sentido y para quién no.

No dice que el trading sea una estafa ni una oportunidad. Es una actividad con unas probabilidades concretas, y la decisión es tuya.',
  total_modules = 3, total_lessons = 9
 WHERE slug = 'introduccion-al-trading-de-criptomonedas';

