-- 1.1 que-es-el-trading
INSERT INTO public.lessons (id, course_id, module_id, title, slug, description, order_index, content)
VALUES ('5b9bba5e-f0ac-4755-b714-1a66f8c32495', '7efb8a11-7120-4e7f-9b49-20ed29b157e5', '67f337df-bb2c-47fb-b58a-ef93e922746f', 'Qué es el trading', 'que-es-el-trading', 'Qué es operar con precisión, qué hace este curso y qué no hace, y por qué no existe la operación segura.', 0, '<h3>🎯 Objetivo de la lección</h3><p>Entender qué es hacer trading con precisión, distinguirlo de lo que se le parece, y saber desde el principio qué hace este curso y qué no hace, porque eso condiciona todo lo que viene después.</p><hr><h3>🚧 Lo que este curso no es</h3><p>Empezamos por aquí porque es lo más honesto y evita un malentendido caro.</p><p><strong>Este curso no enseña a operar.</strong> No vas a encontrar cuándo entrar, dónde poner un límite de pérdidas, qué parte del capital arriesgar, qué indicadores mirar ni qué estrategia seguir. No es un olvido ni un adelanto de un curso de pago: es una decisión.</p><p>El motivo es sencillo. Esas decisiones dependen de tu situación, de tu dinero y de tu tolerancia al riesgo, y quien no te conoce no puede tomarlas por ti. Cualquiera que te las dé en un curso general está vendiéndote una plantilla.</p><p><strong>Lo que sí hace este curso</strong> es responder a dos preguntas que casi nadie responde antes de empezar:</p><ul><li><p><strong>¿Qué es exactamente esta actividad</strong> y en qué se diferencia de otras que se le parecen?</p></li><li><p><strong>¿Por qué casi nadie gana dinero con ella</strong>, y qué tendría que ser cierto para que tú sí?</p></li></ul><p>Con eso puedes decidir si quieres meterte. Si decides que sí, harás bien en aprender la parte operativa en otro sitio, con calma y sabiendo qué buscas.</p><hr><h3>📊 Qué es hacer trading</h3><p>Comprar y vender con el objetivo de aprovechar movimientos de precio en plazos cortos.</p><p>Las dos mitades importan. <strong>El objetivo es el movimiento del precio</strong>, no el uso de lo comprado ni lo que pueda valer dentro de diez años. Y <strong>el plazo es corto</strong>: minutos, días, semanas. Si el plazo se alarga lo suficiente, deja de ser esto y pasa a ser otra cosa.</p><p>De ahí salen tres consecuencias prácticas:</p><ul><li><p><strong>Exige atención sostenida.</strong> Las decisiones se toman en momentos concretos que no eliges tú. No es una actividad que se pueda hacer distraído.</p></li><li><p><strong>El precio es lo único que importa.</strong> Da igual si lo que operas te parece útil, prometedor o absurdo. Solo cuenta si se mueve y en qué dirección.</p></li><li><p><strong>Cada operación es una decisión bajo incertidumbre.</strong> No hay forma de saber qué hará el precio. Hay estimaciones con una probabilidad asociada, y nada más.</p></li></ul><hr><h3>🎲 Probabilidad, no certeza</h3><p>Conviene detenerse aquí porque es donde más gente entra con la idea equivocada.</p><p>En trading <strong>no existe la operación segura</strong>. No es que sea rara: es que no existe, por la misma razón por la que nadie sabe qué hará el precio mañana. Lo que existe son decisiones con una probabilidad de acertar, un beneficio si aciertas y una pérdida si no.</p><p>Esto tiene una consecuencia que cuesta asimilar: <strong>acertar y decidir bien son cosas distintas</strong>. Se puede tomar una decisión razonable y perder dinero, y se puede tomar una decisión pésima y ganarlo. Con pocas operaciones no hay forma de distinguir una cosa de otra.</p><p>Es lo contrario de casi cualquier otra actividad, donde hacerlo bien y que salga bien van de la mano.</p><hr><h3>🔀 Tres cosas que se confunden</h3><p>Hay tres formas distintas de tener criptomonedas, y mezclarlas produce la mayoría de los disgustos. La lección siguiente las compara en detalle; aquí basta con separarlas.</p><ul><li><p><strong>Usarlas.</strong> Enviar, recibir, pagar. El precio importa poco: lo que importa es que funcione. Es de lo que trata <em>Uso práctico de Bitcoin</em>.</p></li><li><p><strong>Mantenerlas.</strong> Comprar y guardar durante años, sin operar. La atención requerida es mínima y el resultado depende de qué pase en ese plazo largo.</p></li><li><p><strong>Operarlas.</strong> Comprar y vender buscando el movimiento a corto plazo. Es de lo que trata este curso.</p></li></ul><p>Son actividades distintas, con exigencias distintas y riesgos distintos. <strong>Este curso no dice cuál conviene</strong>, entre otras cosas porque eso depende de cada persona.</p><hr><h3>⏱️ Qué cuesta que no es dinero</h3><p>Una parte del coste no aparece nunca en las cuentas y conviene ponerla sobre la mesa antes de decidir.</p><p><strong>Tiempo.</strong> Seguir un mercado, revisar posiciones y estudiar lo que salió mal ocupa horas reales, todas las semanas, durante mucho tiempo.</p><p><strong>Atención.</strong> Un mercado abierto todos los días del año no se apaga cuando tú te vas. Eso tiene un efecto sobre el descanso y sobre la capacidad de concentrarse en otras cosas.</p><p><strong>Desgaste.</strong> Perder dinero propio, aunque sea poco, se nota. Y a diferencia de otras actividades, aquí el resultado llega constantemente y en forma de número.</p><p>Nada de esto convierte al trading en mala idea. Son <strong>parte del precio</strong>, y hay que contarlos junto al dinero para saber qué se está pagando.</p><hr><h3>📌 En resumen</h3><ul><li><p><strong>Este curso no enseña a operar</strong>, a propósito: esas decisiones dependen de tu situación y quien no te conoce no puede tomarlas por ti. Responde a qué es esto y por qué casi nadie gana.</p></li><li><p>Hacer trading es <strong>aprovechar movimientos de precio en plazos cortos</strong>. El objetivo es el precio; el plazo es corto.</p></li><li><p>Exige <strong>atención sostenida</strong>, el precio es lo único que cuenta y cada operación es una decisión bajo incertidumbre.</p></li><li><p><strong>No existe la operación segura.</strong> Y acertar y decidir bien son cosas distintas: con pocas operaciones no se pueden distinguir.</p></li><li><p>Usar, mantener y operar son <strong>tres actividades distintas</strong>. El curso no dice cuál conviene.</p></li><li><p>Parte del coste no es dinero: <strong>tiempo, atención y desgaste</strong>.</p></li></ul><hr><h3>➡️ Qué viene después</h3><p>Con la actividad delimitada, la siguiente lección compara las tres formas de relacionarse con un activo —usarlo, mantenerlo y operarlo— por lo que exige cada una, sin decidir por ti cuál tiene más sentido.</p>')
ON CONFLICT (id) DO UPDATE SET module_id = EXCLUDED.module_id, title = EXCLUDED.title,
  slug = EXCLUDED.slug, description = EXCLUDED.description, order_index = EXCLUDED.order_index,
  content = EXCLUDED.content;

-- 1.2 trading-inversion-y-uso
INSERT INTO public.lessons (id, course_id, module_id, title, slug, description, order_index, content)
VALUES ('16e0aff9-831e-418a-a7c3-629c40f3b4df', '7efb8a11-7120-4e7f-9b49-20ed29b157e5', '67f337df-bb2c-47fb-b58a-ef93e922746f', 'Usar, mantener y operar', 'trading-inversion-y-uso', 'Tres formas de relacionarse con un activo, comparadas por lo que exige cada una y no por cuál conviene.', 1, '<h3>🎯 Objetivo de la lección</h3><p>Comparar las tres formas de relacionarse con un activo —usarlo, mantenerlo y operarlo— por lo que exige cada una y por lo que puede salir mal, sin afirmar cuál conviene. Porque eso depende de cada persona y no de este curso.</p><hr><h3>🧭 Por qué esta comparación y no otra</h3><p>Lo habitual es comparar «trading» con «inversión» y adjudicar a cada uno un perfil: el impaciente y el paciente, el que arriesga y el prudente. Esa comparación es cómoda y dice poco, porque convierte una decisión técnica en un rasgo de carácter.</p><p>Aquí se comparan por lo comprobable: <strong>qué exige cada una, en qué plazo se sabe el resultado y qué tiene que pasar para perder</strong>. Con eso cada uno puede ver dónde encaja, si es que encaja en alguna.</p><hr><h3>🛠️ Usarlas</h3><p><strong>Qué es:</strong> tener la cantidad que vas a mover para enviar, recibir o pagar.</p><p><strong>Qué exige:</strong> saber operar con la herramienta y comprobar antes de firmar. Poco tiempo, y casi todo concentrado al principio, mientras aprendes.</p><p><strong>Qué mira el precio:</strong> poco. Importa en el momento de cambiar a otra moneda y ya está.</p><p><strong>Qué puede salir mal:</strong> errores prácticos —una dirección mal copiada, una red equivocada— y engaños. Todo ello está tratado en <em>Uso práctico de Bitcoin</em> y en <em>Seguridad básica</em>.</p><hr><h3>📦 Mantenerlas</h3><p><strong>Qué es:</strong> comprar y guardar durante años, sin operar en función del precio.</p><p><strong>Qué exige:</strong> resolver bien la custodia una vez y sostenerla en el tiempo. Atención mínima en el día a día, y mucha disciplina para no hacer nada cuando el precio se mueve mucho.</p><p><strong>Qué mira el precio:</strong> nada, hasta el día que se vende. Esa es la premisa.</p><p><strong>Qué puede salir mal:</strong> dos cosas de naturaleza distinta. Que el precio, en el plazo que sea, esté por debajo de donde compraste. Y que pierdas el acceso a lo guardado, que es el riesgo que se subestima y del que se ocupa <em>Seguridad básica</em>.</p><p>Una advertencia sobre esto, porque es donde se cuela la frase que este curso evita: <strong>nadie puede afirmar que mantener durante años funcione</strong>. Puede salir bien o mal, y que haya salido bien antes no dice qué hará después. Lo único describible es lo que exige, no lo que produce.</p><hr><h3>📈 Operarlas</h3><p><strong>Qué es:</strong> comprar y vender buscando movimientos a corto plazo.</p><p><strong>Qué exige:</strong> atención continuada, decisiones frecuentes y capacidad de sostener el proceso cuando el resultado va en contra. Es la más intensiva de las tres con diferencia.</p><p><strong>Qué mira el precio:</strong> todo. Es lo único que produce resultado.</p><p><strong>Qué puede salir mal:</strong> perder en una operación concreta, acumular pérdidas por costes que no se contaron —lección 2.1—, o perder mucho más rápido de lo previsto si hay apalancamiento de por medio —lección 2.2—.</p><hr><h3>📐 Las tres, en la misma tabla</h3><p>Resumido por lo que se puede comprobar:</p><ul><li><p><strong>Atención requerida:</strong> baja al usar, baja al mantener —salvo la decisión inicial—, alta al operar.</p></li><li><p><strong>Cuándo sabes el resultado:</strong> al momento cuando usas, en años cuando mantienes, en cada operación cuando operas.</p></li><li><p><strong>Qué habilidad pide:</strong> manejo de herramientas, disciplina para no actuar, y proceso sostenido bajo presión, respectivamente.</p></li><li><p><strong>Qué parte del resultado depende de ti:</strong> casi toda al usar, casi ninguna al mantener, y una parte al operar, que es justo lo que hace que sea difícil de medir.</p></li></ul><p>Fíjate en la última. <strong>Al mantener, el resultado no depende de tus decisiones después de comprar; al operar, depende de muchas decisiones y del azar a la vez</strong>, y separar lo uno de lo otro exige muchísimas operaciones.</p><hr><h3>🔗 No son excluyentes</h3><p>Se presentan como bandos y no lo son. Lo habitual es combinar: una cantidad pequeña para usar, otra que no se toca, y —si se decide— otra separada para operar.</p><p>Lo que sí conviene es <strong>que no se mezclen</strong>. Cuando el dinero de operar y el de mantener están en el mismo sitio, es fácil que una mala racha se coma lo que no estaba destinado a eso, y que una posición pensada para días se convierta en años por no aceptar la pérdida. Es un fallo frecuente y no tiene nada de técnico.</p><hr><h3>🎯 La pregunta útil</h3><p>No es «¿qué es mejor?». Es esta:</p><p><strong>¿Qué esperas conseguir, y cuál de las tres actividades produce eso?</strong></p><ul><li><p>Si lo que quieres es <strong>pagar y cobrar sin intermediarios</strong>, lo que necesitas es usarlas. Operar no aporta nada.</p></li><li><p>Si lo que quieres es <strong>exposición a lo que ocurra en años</strong>, mantener hace eso. Operar añade decisiones que no hacen falta.</p></li><li><p>Si lo que quieres es <strong>obtener resultado de los movimientos a corto plazo</strong>, eso es operar, y el resto del curso trata de qué implica.</p></li></ul><p>Y una cuarta posibilidad que conviene nombrar: si lo que quieres es <strong>ganar dinero rápido</strong>, ninguna de las tres está diseñada para eso, y el módulo siguiente explica por qué con números.</p><hr><h3>📌 En resumen</h3><ul><li><p>Comparar por «paciencia» frente a «disciplina» dice poco. Se comparan por <strong>qué exigen, en qué plazo se ve el resultado y qué tiene que pasar para perder</strong>.</p></li><li><p><strong>Usar</strong> pide manejo de herramientas; <strong>mantener</strong> pide resolver la custodia y no actuar; <strong>operar</strong> pide atención continuada y proceso bajo presión.</p></li><li><p><strong>Nadie puede afirmar que mantener durante años funcione.</strong> Se puede describir lo que exige, no lo que produce.</p></li><li><p>Al mantener, el resultado no depende de tus decisiones posteriores. Al operar depende <strong>de muchas decisiones y del azar a la vez</strong>, y separarlos exige muchísimas operaciones.</p></li><li><p>No son excluyentes, pero <strong>conviene que no se mezclen</strong>: una mala racha no debería comerse lo que no estaba destinado a eso.</p></li><li><p>La pregunta no es cuál es mejor, sino <strong>qué esperas conseguir y cuál de las tres produce eso</strong>.</p></li></ul><hr><h3>➡️ Qué viene después</h3><p>Antes de entrar en por qué casi nadie gana, hace falta una pieza que ordena el resto: <strong>de dónde sale el dinero que gana un operador</strong>. La respuesta explica muchas cosas y no suele contarse.</p>')
ON CONFLICT (id) DO UPDATE SET module_id = EXCLUDED.module_id, title = EXCLUDED.title,
  slug = EXCLUDED.slug, description = EXCLUDED.description, order_index = EXCLUDED.order_index,
  content = EXCLUDED.content;

-- 1.3 de-donde-sale-el-dinero  (NUEVA)
INSERT INTO public.lessons (id, course_id, module_id, title, slug, description, order_index, content)
VALUES ('05bea3e9-d524-4713-8fe1-bd6bbb934e18', '7efb8a11-7120-4e7f-9b49-20ed29b157e5', '67f337df-bb2c-47fb-b58a-ef93e922746f', 'De dónde sale el dinero', 'de-donde-sale-el-dinero', 'Cuando alguien gana operando, ese dinero sale de algún sitio. Quién está al otro lado y qué implica.', 2, '<h3>🎯 Objetivo de la lección</h3><p>Responder a una pregunta que casi nunca se hace: cuando alguien gana operando, ¿de dónde sale ese dinero? La respuesta ordena todo el módulo siguiente y explica por qué las proporciones son las que son.</p><hr><h3>💰 La pregunta incómoda</h3><p>Si operar produce beneficio, ese beneficio viene de algún sitio. No lo crea el mercado ni aparece por el movimiento del precio: <strong>sale del bolsillo de alguien</strong>. Saber de quién, y en qué condiciones, dice más sobre esta actividad que cualquier explicación de gráficos.</p><p>La respuesta no es la misma en todos los casos, y la diferencia importa.</p><hr><h3>⚖️ Cuando la suma es cero</h3><p>Hay instrumentos —futuros, contratos por diferencias y similares— en los que una parte gana exactamente lo que la otra pierde. No se compra nada: se apuesta sobre el movimiento del precio contra alguien que apuesta lo contrario.</p><p>Ahí el reparto es aritmético: <strong>de cada euro que gana un lado, ese euro lo pone el otro lado.</strong> Y como además hay costes, la suma de todos los participantes es <em>menor</em> que cero: entre todos pierden lo que se llevan las comisiones.</p><p>Esto no es una opinión sobre el instrumento. Es cómo está construido.</p><hr><h3>🔄 Cuando no es exactamente así</h3><p>Comprar y vender el activo en sí —lo que se llama mercado al contado— no funciona igual, y conviene decirlo para no exagerar.</p><p>Si compras algo y meses después vale más, quien te lo vendió no ha «perdido» esa diferencia: vendió a un precio que en su momento aceptó, y puede haber hecho con ese dinero otra cosa que le fue bien. Los dos podéis salir ganando en el mismo periodo. <strong>El contado no es un juego de suma cero a largo plazo.</strong></p><p>Pero para el trading a corto plazo, que es de lo que trata este curso, la cosa se parece bastante al primer caso. Si tu resultado viene de comprar barato a alguien que vendía y vender caro a alguien que compraba, en ese intercambio concreto y en ese plazo concreto <strong>tu ganancia es la peor ejecución de otro</strong>.</p><p>La diferencia con los futuros es real y es de grado, no de naturaleza.</p><hr><h3>🏢 Quién está al otro lado</h3><p>Esta es la parte que más ajusta las expectativas, y no requiere creer en conspiraciones.</p><p>Cuando haces una operación, enfrente no suele haber alguien como tú. Buena parte del volumen de estos mercados lo mueven <strong>participantes profesionales</strong>: empresas dedicadas exclusivamente a esto, con sistemas automáticos, con equipos, con acceso a datos mejores y más rápidos, y con costes por operación mucho más bajos que los tuyos.</p><p>No hacen trampas ni te tienen fichado. Sencillamente <strong>hacen la misma actividad con más medios y a tiempo completo</strong>.</p><p>Eso no significa que sea imposible ganar. Significa que conviene saber con quién compartes mesa, y que la comparación adecuada no es contra la suerte, sino contra gente que lleva años optimizando esto.</p><hr><h3>🧮 Qué implica para el reparto</h3><p>Uniendo las dos piezas —que el resultado sale de otro participante y que muchos participantes son profesionales— se entiende por qué el reparto no es simétrico.</p><p>Si el dinero que gana un lado lo pone el otro, y además hay un coste fijo por participar, entonces <strong>no puede ser que la mayoría gane</strong>. No es una estadística desafortunada: es aritmética. La distribución habitual es la de muchos perdiendo poco a poco y unos pocos ganando bastante.</p><p>Es el mismo mecanismo que hace que en cualquier actividad competitiva con costes de entrada la mayoría quede por debajo de la media. Aquí solo es más visible porque el resultado se mide en dinero y se ve todos los días.</p><hr><h3>🎯 Qué tendría que ser cierto</h3><p>De aquí sale la pregunta que conviene hacerse antes de empezar, y que este curso no puede responder por ti:</p><p><strong>¿Qué tendrías tú que hacer sistemáticamente mejor que quien está al otro lado?</strong></p><p>No «mejor que el mercado», que no quiere decir nada, sino mejor que los participantes concretos con los que vas a intercambiar. Las respuestas posibles existen —operar en plazos o mercados donde los grandes no entran, tener menos prisa que ellos, aprovechar que no necesitas justificar resultados a nadie— y todas exigen ser muy concreto.</p><p>Si la respuesta es «esforzarme» o «formarme», conviene saber que <strong>es lo mismo que responde todo el mundo</strong>, incluidos los que están al otro lado.</p><hr><h3>🚫 Lo que esto no demuestra</h3><p>Para no pasarse de frenada en la dirección contraria:</p><ul><li><p><strong>No demuestra que sea una estafa.</strong> Es una actividad legal con reglas conocidas, y los costes están publicados.</p></li><li><p><strong>No demuestra que nadie gane.</strong> Hay quien gana de forma sostenida; son pocos y suelen dedicarse a ello por completo.</p></li><li><p><strong>No demuestra que no debas hacerlo.</strong> Esa decisión es tuya y requiere saber esto antes, no después.</p></li></ul><p>Lo que sí demuestra es que <strong>el resultado medio no puede ser positivo</strong>, y que cualquier presentación que lo dé a entender está omitiendo de dónde sale el dinero.</p><hr><h3>📌 En resumen</h3><ul><li><p>El beneficio de operar no lo crea el mercado: <strong>sale del bolsillo de otro participante</strong>.</p></li><li><p>En futuros y contratos por diferencias es <strong>aritmético</strong>: lo que gana un lado lo pone el otro, y con los costes la suma total es menor que cero.</p></li><li><p>En el contado a largo plazo no es suma cero. Pero <strong>en el corto plazo se le parece bastante</strong>: tu ganancia es la peor ejecución de otro.</p></li><li><p>Al otro lado suele haber <strong>participantes profesionales</strong>, con sistemas automáticos y costes más bajos. No hacen trampas: hacen lo mismo con más medios.</p></li><li><p>Por eso <strong>no puede ser que la mayoría gane</strong>. Es aritmética, no mala suerte.</p></li><li><p>La pregunta que hay que responderse: <strong>¿qué harías sistemáticamente mejor que quien está al otro lado?</strong> «Formarme» es lo que responde todo el mundo.</p></li></ul><hr><h3>➡️ Qué viene después</h3><p>Ya sabes de dónde sale el dinero. El módulo siguiente entra en por qué casi nadie gana, empezando por la parte más medible y la que menos se cuenta: <strong>los costes que no aparecen en ninguna cuenta</strong> y que mueven el punto de equilibrio.</p>')
ON CONFLICT (id) DO UPDATE SET module_id = EXCLUDED.module_id, title = EXCLUDED.title,
  slug = EXCLUDED.slug, description = EXCLUDED.description, order_index = EXCLUDED.order_index,
  content = EXCLUDED.content;

-- 2.1 las-cuentas-que-no-se-hacen
INSERT INTO public.lessons (id, course_id, module_id, title, slug, description, order_index, content)
VALUES ('4671f914-684c-47ef-b22d-cd6ba3281e00', '7efb8a11-7120-4e7f-9b49-20ed29b157e5', '91a8bd69-3c05-4b92-94aa-5025ffa77814', 'Las cuentas que no se hacen', 'las-cuentas-que-no-se-hacen', 'Comisión, horquilla y deslizamiento: por qué el punto de equilibrio no está donde crees.', 0, '<h3>🎯 Objetivo de la lección</h3><p>Ver los costes que no aparecen en ninguna cuenta y entender por qué el punto a partir del cual ganas no está donde crees. Es la parte más medible de por qué casi nadie gana, y la que menos se cuenta.</p><hr><h3>🧾 El coste que sí se ve</h3><p>La comisión por operar está publicada y suele parecer pequeña: una fracción de porcentaje por cada compra y por cada venta.</p><p>Lo que la hace grande no es el tamaño, es la <strong>frecuencia</strong>. Un coste pequeño aplicado muchas veces se convierte en el gasto principal de la actividad. Quien hace una operación al mes y quien hace diez al día pagan por el mismo servicio cantidades que no se parecen en nada.</p><p>De ahí una consecuencia que conviene tener clara: <strong>operar más no es esforzarse más</strong>. Cada operación tiene un peaje, y el peaje se cobra igual si acertaste que si no.</p><hr><h3>↔️ El coste que casi no se ve</h3><p>En cualquier mercado hay dos precios a la vez: uno al que puedes comprar ya y otro, algo más bajo, al que puedes vender ya. La distancia entre ambos se llama <strong>horquilla</strong>, y es un coste real aunque no aparezca como tal en ningún sitio.</p><p>Significa algo incómodo: <strong>en el instante en que abres una posición ya estás perdiendo</strong>, aunque el precio no se haya movido. Si compras y vendes inmediatamente, recuperas menos de lo que pusiste.</p><p>La horquilla se ensancha cuando hay poca actividad y cuando hay movimientos bruscos, que es justo cuando más tentador resulta operar. Y es mucho más ancha en activos poco negociados que en los principales.</p><hr><h3>🌊 El coste que aparece en el peor momento</h3><p>Cuando la cantidad que quieres mover es grande respecto a lo que hay disponible al mejor precio, tu propia operación mueve el precio en tu contra mientras se ejecuta. Se llama <strong>deslizamiento</strong>.</p><p>Tiene dos propiedades desagradables:</p><ul><li><p><strong>Es impredecible.</strong> No lo conoces antes; lo descubres al ver a qué precio se ejecutó.</p></li><li><p><strong>Empeora cuando más falta hace que no lo haga.</strong> En momentos de pánico, cuando todo el mundo quiere salir a la vez, es cuando más caro sale salir.</p></li></ul><p>Aquí aparece la <strong>liquidez</strong>, que es simplemente cuánta actividad hay: cuanta menos, más ancha la horquilla y mayor el deslizamiento. Un mercado con poca liquidez es cómodo para entrar y caro para salir, y eso no se nota hasta el día que quieres salir.</p><hr><h3>🕳️ Los que ni se cuentan</h3><p>Tres más que suelen quedarse fuera de las cuentas:</p><p><strong>El coste de financiación.</strong> Si se opera con apalancamiento, muchos productos cobran una tasa periódica por mantener la posición abierta. Cuanto más dura, más cuesta, independientemente del precio. Lo vemos en la lección siguiente.</p><p><strong>Las conversiones.</strong> Entrar y salir de dinero del banco tiene su propia comisión y su propio tipo de cambio, y a veces es el coste mayor de toda la operación.</p><p><strong>Los impuestos.</strong> Existen, dependen del país y no se pagan con lo que quede al final, sino según lo que marque cada norma. Tiene lección propia, la 3.2, porque es de lo que más sorprende.</p><hr><h3>🎯 Dónde queda el punto de equilibrio</h3><p>Aquí está la idea que ordena la lección entera.</p><p>Es natural pensar que si aciertas más veces de las que fallas, ganas. <strong>No es así.</strong> El punto a partir del cual el resultado es positivo no está en acertar la mitad de las veces: está más arriba, y cuánto más arriba depende de cuántos costes acumules.</p><p>Con comisión en cada entrada y en cada salida, más la horquilla, más el deslizamiento, <strong>cada operación empieza en negativo</strong>. El movimiento del precio tiene que cubrir primero todo eso y solo después empieza a producir resultado.</p><p>Dos consecuencias que se deducen solas:</p><ul><li><p><strong>Cuanto más corto el plazo, más pesa el coste.</strong> Si buscas movimientos pequeños, el peaje se come una parte grande de cada uno.</p></li><li><p><strong>Cuanto más operas, más arriba está tu punto de equilibrio.</strong> La actividad que parece esfuerzo es también la que sube el listón.</p></li></ul><hr><h3>🔍 Cómo se mide esto de verdad</h3><p>Sin entrar en cómo operar, hay una forma honesta de mirar un resultado, y casi nadie la usa:</p><p><strong>Cuenta todo lo que saliste ingresando y todo lo que metiste, en un periodo largo.</strong> No operación a operación, no en porcentajes, no comparando con el mejor momento. Dinero que entró menos dinero que salió, contando comisiones, conversiones y el tiempo que le dedicaste.</p><p>La razón por la que casi nadie lo hace así es que <strong>es la única medida que no se puede maquillar</strong>. El recuento operación a operación permite recordar las buenas; el porcentaje permite elegir desde cuándo se mide; la comparación con el máximo permite sentirse bien con una pérdida.</p><hr><h3>📌 En resumen</h3><ul><li><p>La comisión es pequeña pero se cobra <strong>en cada entrada y en cada salida</strong>. Lo que la hace grande es la frecuencia: operar más no es esforzarse más.</p></li><li><p>La <strong>horquilla</strong> hace que en el instante de abrir ya estés perdiendo, aunque el precio no se mueva.</p></li><li><p>El <strong>deslizamiento</strong> es impredecible y empeora justo cuando más falta hace que no lo haga.</p></li><li><p>Poca liquidez significa <strong>cómodo para entrar y caro para salir</strong>, y no se nota hasta que quieres salir.</p></li><li><p><strong>El punto de equilibrio no está en acertar la mitad de las veces</strong>: está más arriba, y sube cuanto más operas y más corto es el plazo.</p></li><li><p>La única medida que no se puede maquillar: <strong>dinero que entró menos dinero que salió</strong>, en un periodo largo.</p></li></ul><hr><h3>➡️ Qué viene después</h3><p>Los costes explican una parte de las pérdidas. La siguiente lección trata la pieza que explica las pérdidas rápidas y totales, que es distinta: <strong>el apalancamiento</strong>, qué es exactamente y por qué acorta tanto el plazo hasta quedarse sin nada.</p>')
ON CONFLICT (id) DO UPDATE SET module_id = EXCLUDED.module_id, title = EXCLUDED.title,
  slug = EXCLUDED.slug, description = EXCLUDED.description, order_index = EXCLUDED.order_index,
  content = EXCLUDED.content;

-- 2.2 el-apalancamiento  (NUEVA)
INSERT INTO public.lessons (id, course_id, module_id, title, slug, description, order_index, content)
VALUES ('7fa99c16-76e8-4081-b7f6-ae393c39f404', '7efb8a11-7120-4e7f-9b49-20ed29b157e5', '91a8bd69-3c05-4b92-94aa-5025ffa77814', 'El apalancamiento', 'el-apalancamiento', 'Qué es, qué es una liquidación y por qué acorta tanto el plazo hasta quedarse sin nada.', 1, '<h3>🎯 Objetivo de la lección</h3><p>Entender qué es el apalancamiento, por qué multiplica igual en las dos direcciones, qué es una liquidación y por qué acorta tanto el plazo hasta quedarse sin nada. Sin decirte cuánto usar: el objetivo es que tengas la pieza antes de decidir.</p><hr><h3>🔎 Qué es exactamente</h3><p>Apalancarse es <strong>operar con una cantidad mayor de la que has puesto</strong>. Pones una parte, el intermediario aporta el resto, y las ganancias y las pérdidas se calculan sobre el total.</p><p>Con un ejemplo mínimo. Pones 100 y operas con 1.000, lo que se anuncia como «diez veces». Entonces:</p><ul><li><p>Si el precio sube un 1 %, ganas 10 sobre tus 100. Un <strong>10 %</strong>.</p></li><li><p>Si el precio baja un 1 %, pierdes 10 de tus 100. Un <strong>10 %</strong>.</p></li></ul><p>Esa es toda la mecánica. <strong>Multiplica el movimiento del precio, en los dos sentidos, por igual.</strong> No es un producto de riesgo por sí mismo ni una trampa: es una multiplicación.</p><p>Lo que lo hace peligroso no es la multiplicación. Es lo que viene ahora.</p><hr><h3>⛔ La liquidación</h3><p>La parte que cambia la naturaleza de la cosa, y la que menos se explica.</p><p>El dinero que aporta el intermediario no es un regalo: es suyo y quiere recuperarlo. Para asegurarse, vigila tu posición constantemente y <strong>la cierra automáticamente en cuanto las pérdidas se acercan a lo que tú pusiste</strong>. Eso es una liquidación.</p><p>Tres cosas que conviene entender de ella:</p><ul><li><p><strong>No te avisa ni te pregunta.</strong> Ocurre cuando ocurre, aunque estés durmiendo.</p></li><li><p><strong>Es definitiva.</strong> La posición se cierra y la pérdida se realiza. Si el precio vuelve cinco minutos después, ya no estás dentro.</p></li><li><p><strong>Cuanto mayor el multiplicador, menos margen hay.</strong> Con diez veces, un movimiento del 10 % en tu contra basta. Con veinte, un 5 %. Con cien, un 1 %.</p></li></ul><p>Esa última línea es la lección entera. <strong>El apalancamiento no aumenta la probabilidad de que el precio vaya en tu contra: reduce cuánto tiene que ir en tu contra para que lo pierdas todo.</strong></p><hr><h3>📉 Por qué la asimetría es inevitable</h3><p>Hay algo que la mecánica de multiplicar esconde y que conviene ver con números.</p><p>Perder un 50 % y ganar un 50 % no se compensan. Si tienes 100 y pierdes la mitad, te quedan 50. Para volver a 100 no necesitas ganar un 50 %, necesitas <strong>ganar un 100 %</strong>.</p><p>Cuanto más profunda la pérdida, peor la proporción: recuperarse de un −80 % exige un +400 %. Y con apalancamiento las pérdidas profundas llegan con movimientos de precio pequeños, así que <strong>se entra en esa zona mucho antes</strong>.</p><p>Esto no depende de tu habilidad ni de tu estrategia. Es aritmética, igual que lo de la lección anterior.</p><hr><h3>⏳ Por qué acorta el plazo</h3><p>Juntando las tres piezas —multiplicación, liquidación y asimetría— se entiende el efecto que da nombre a esta lección.</p><p>Sin apalancamiento, un movimiento del 30 % en tu contra es un mal momento del que se puede salir. <strong>Con apalancamiento suficiente, ese mismo movimiento es el final</strong>, y además no hacía falta que llegara al 30 %: bastó con el punto en que se disparó la liquidación.</p><p>Añade que estos mercados funcionan todos los días del año y que los movimientos bruscos ocurren a cualquier hora, y queda claro por qué el plazo hasta quedarse sin nada se acorta tanto. <strong>No hace falta equivocarse muchas veces. Basta con una, en el momento malo.</strong></p><p>Y conviene recordar el coste de financiación de la lección anterior: mantener una posición apalancada abierta cuesta dinero cada día, así que el tiempo también juega en contra.</p><hr><h3>🧊 Dos cosas que empeoran el conjunto</h3><p><strong>La cascada.</strong> Cuando el precio cae y se disparan muchas liquidaciones a la vez, esos cierres forzosos son ventas, y esas ventas empujan el precio más abajo, lo que dispara más liquidaciones. Es un mecanismo que se retroalimenta y explica las caídas muy rápidas que aparecen de vez en cuando.</p><p><strong>El deslizamiento, otra vez.</strong> La liquidación se ejecuta al precio que haya, no al que estaba previsto. En una caída brusca con poca liquidez puede cerrarse bastante peor, y en algunos casos quedar un saldo negativo. Conviene saber si el producto que se usa protege contra eso o no, porque no todos lo hacen.</p><hr><h3>🗣️ Cómo se presenta</h3><p>Una observación sobre el lenguaje, porque ayuda a leer lo que verás.</p><p>El apalancamiento se anuncia casi siempre por lo que multiplica al ganar y casi nunca por lo que reduce el margen antes de perderlo todo. «Hasta cien veces» describe la misma propiedad que «un movimiento del 1 % en tu contra acaba con tu posición», pero se elige la primera forma.</p><p>No hay nada oculto: las condiciones están publicadas. <strong>Lo que está sesgado es qué mitad se destaca</strong>, y saberlo ya cambia cómo se lee un anuncio.</p><p>Conviene añadir un dato comprobable: en varios países los reguladores han limitado el apalancamiento disponible para particulares o han restringido la publicidad de estos productos, precisamente por las proporciones de pérdidas observadas. Los límites concretos cambian según dónde vivas.</p><hr><h3>📌 En resumen</h3><ul><li><p>Apalancarse es <strong>operar con más de lo que has puesto</strong>. Multiplica el movimiento del precio en los dos sentidos por igual: es una multiplicación, no una trampa.</p></li><li><p>Lo que cambia la naturaleza es la <strong>liquidación</strong>: el cierre automático cuando las pérdidas se acercan a lo que pusiste. No avisa, es definitiva y no espera a que el precio vuelva.</p></li><li><p><strong>No aumenta la probabilidad de que el precio vaya en tu contra: reduce cuánto tiene que ir</strong> para perderlo todo. Diez veces → 10 %; cien veces → 1 %.</p></li><li><p>Perder y ganar el mismo porcentaje no se compensan: de un −50 % se sale con un <strong>+100 %</strong>. Y con apalancamiento se llega antes a esa zona.</p></li><li><p>Las <strong>cascadas de liquidaciones</strong> se retroalimentan, y la ejecución puede ser peor de lo previsto. No todos los productos protegen contra el saldo negativo.</p></li><li><p>Se anuncia por lo que multiplica al ganar, no por el margen que quita. <strong>Lo sesgado es qué mitad se destaca.</strong></p></li></ul><hr><h3>➡️ Qué viene después</h3><p>Los costes y el apalancamiento explican la parte mecánica. Falta la que explica por qué gente que sabe todo esto pierde igual: <strong>lo que hace la cabeza</strong> cuando hay dinero propio en juego y el resultado llega en forma de número todos los días.</p>')
ON CONFLICT (id) DO UPDATE SET module_id = EXCLUDED.module_id, title = EXCLUDED.title,
  slug = EXCLUDED.slug, description = EXCLUDED.description, order_index = EXCLUDED.order_index,
  content = EXCLUDED.content;

-- 2.3 lo-que-hace-la-cabeza
INSERT INTO public.lessons (id, course_id, module_id, title, slug, description, order_index, content)
VALUES ('846d57cf-7834-49f3-a152-683476adc1ca', '7efb8a11-7120-4e7f-9b49-20ed29b157e5', '91a8bd69-3c05-4b92-94aa-5025ffa77814', 'Lo que hace la cabeza', 'lo-que-hace-la-cabeza', 'Por qué pierde dinero quien sabe todo lo anterior. No es falta de carácter: son mecanismos concretos.', 2, '<h3>🎯 Objetivo de la lección</h3><p>Entender por qué gente que sabe perfectamente todo lo anterior pierde dinero igual. No por debilidad de carácter, sino porque esta actividad activa mecanismos mentales concretos que funcionan bien en casi todo lo demás y aquí funcionan en contra.</p><hr><h3>🧠 El error no es de carácter</h3><p>La explicación habitual —falta de disciplina, exceso de avaricia, miedo— tiene el problema de que convierte un fenómeno regular en un defecto personal. Si le pasa a casi todo el mundo, incluida gente serena y capaz en otros terrenos, la explicación individual se queda corta.</p><p>Lo que ocurre es más interesante: <strong>el trading combina tres cosas que nuestra cabeza gestiona mal a la vez</strong>. Resultado inmediato, resultado parcialmente aleatorio, y dinero propio. Cada una por separado es manejable. Juntas producen un comportamiento bastante predecible.</p><hr><h3>⚖️ Perder pesa más que ganar</h3><p>Está medido desde hace décadas y fuera de este contexto: <strong>perder una cantidad molesta bastante más de lo que agrada ganar esa misma cantidad</strong>. No es una impresión, es un desequilibrio estable en cómo valoramos.</p><p>Aplicado aquí produce dos conductas que se refuerzan entre sí:</p><ul><li><p><strong>Cerrar pronto lo que va bien</strong>, para asegurar una ganancia pequeña y quitarse la incomodidad.</p></li><li><p><strong>Aguantar lo que va mal</strong>, porque cerrarlo convierte una pérdida provisional en una pérdida definitiva. Mientras no cierras, «todavía puede volver».</p></li></ul><p>Combinadas dan el patrón más común de todos: <strong>muchas ganancias pequeñas y unas pocas pérdidas grandes</strong>. Se puede acertar la mayoría de las veces y terminar perdiendo, que es exactamente lo que le ocurre a mucha gente y lo que hace que el recuento de aciertos engañe tanto.</p><hr><h3>🎰 El azar disfrazado de habilidad</h3><p>Aquí está el mecanismo más difícil de esquivar, y enlaza con la lección 1.1: <strong>acertar y decidir bien son cosas distintas</strong>.</p><p>Como una parte del resultado es aleatoria, una decisión mala puede salir bien varias veces seguidas. Y nuestra cabeza está construida para encontrar patrones y atribuirse el mérito: si sale bien, fue por lo que hice; si sale mal, fue mala suerte o el mercado.</p><p>El efecto práctico es desagradable: <strong>una racha buena por azar refuerza justo el comportamiento que la producirá mala después</strong>, y lo hace sintiéndose como aprendizaje.</p><p>Para distinguir habilidad de suerte hacen falta muchísimas operaciones, muchas más de las que la mayoría llega a hacer. Con veinte o treinta no se puede saber, y con eso suele decidirse si «se me da bien».</p><hr><h3>🔥 Recuperar lo perdido</h3><p>La conducta que más cuentas ha vaciado, y tiene nombre propio en todas las actividades donde hay dinero y azar.</p><p>Después de una pérdida aparece el impulso de recuperarla <em>ya</em>. Y como la pérdida duele en proporción a su tamaño, el impulso empuja a operar más grande, con más apalancamiento o más veces, que es justo lo que amplifica lo siguiente que pase.</p><p>Lo que lo hace particularmente peligroso es que <strong>se siente como determinación y no como impulso</strong>. Se vive como estar enfrentándose al problema en lugar de rendirse, cuando lo que se está haciendo es subir la apuesta después de perder.</p><p>Con el efecto de la lección anterior encima —que de un −50 % se sale con un +100 %— el intento de recuperar rápido es también el que exige más suerte.</p><hr><h3>📱 Lo que el diseño pone de su parte</h3><p>Un factor externo que conviene nombrar, porque no depende de ti.</p><p>Las aplicaciones de estos mercados no son neutras. Están diseñadas para que operar sea rápido y agradable: notificaciones de movimientos, gráficos en color, celebración de las operaciones ganadoras, acceso en dos toques desde el teléfono. Ninguna de esas decisiones está pensada para que operes menos.</p><p>Añade que el mercado está abierto siempre y que no hay horario que te obligue a parar. <strong>No hay ningún momento en que el sistema te diga que es suficiente por hoy</strong>, a diferencia de casi cualquier otra actividad.</p><p>No es una acusación de mala fe: es el modelo de negocio, que cobra por operación. Pero conviene saber que <strong>el entorno empuja en una dirección concreta</strong>.</p><hr><h3>🧩 Por qué saberlo no basta</h3><p>La conclusión incómoda de la lección, y la razón de que exista.</p><p>Todo lo anterior está documentado y es de dominio público. Y aun así les ocurre a personas que lo han leído, porque <strong>estos mecanismos no se desactivan sabiendo que existen</strong>. Actúan en el momento, con dinero propio delante y con prisa, que es cuando menos ayuda el conocimiento.</p><p>Lo que sí cambia con saberlo es otra cosa, y es lo que este curso puede ofrecer: <strong>permite reconocer el estado cuando estás en él</strong>. Notar que llevas media hora mirando la pantalla después de una pérdida, o que acabas de tener tres aciertos seguidos y te sientes especialmente capaz, es información sobre ti que antes no tenías.</p><p>Qué hacer con esa información no lo decide este curso.</p><hr><h3>📌 En resumen</h3><ul><li><p>No es un defecto de carácter: el trading combina <strong>resultado inmediato, azar y dinero propio</strong>, tres cosas que la cabeza gestiona mal juntas.</p></li><li><p>Perder pesa más que ganar, y de ahí salen <strong>ganancias pequeñas aseguradas y pérdidas grandes aguantadas</strong>. Se puede acertar la mayoría de las veces y perder igual.</p></li><li><p>Como parte del resultado es azar, <strong>una racha buena refuerza el comportamiento que la hará mala después</strong>, y se siente como aprendizaje.</p></li><li><p>El impulso de recuperar lo perdido <strong>se siente como determinación</strong>, y es subir la apuesta después de perder.</p></li><li><p>El entorno no es neutro: <strong>nada te dice que es suficiente por hoy</strong>, y el negocio cobra por operación.</p></li><li><p>Saberlo no desactiva nada. Lo que permite es <strong>reconocer el estado cuando estás en él</strong>.</p></li></ul><hr><h3>➡️ Qué viene después</h3><p>Con la parte mecánica y la mental sobre la mesa, el último módulo se ocupa de decidir: <strong>qué se puede esperar razonablemente</strong>, qué obligaciones aparecen aunque pierdas, y cómo responder a la pregunta con la que empezaste.</p>')
ON CONFLICT (id) DO UPDATE SET module_id = EXCLUDED.module_id, title = EXCLUDED.title,
  slug = EXCLUDED.slug, description = EXCLUDED.description, order_index = EXCLUDED.order_index,
  content = EXCLUDED.content;

-- 3.1 expectativas-realistas
INSERT INTO public.lessons (id, course_id, module_id, title, slug, description, order_index, content)
VALUES ('357ad0f4-83a1-471e-ad7b-e5d3a8006e0c', '7efb8a11-7120-4e7f-9b49-20ed29b157e5', 'ac33c06e-442a-4756-ac74-b8a86ca634f8', 'Expectativas realistas', 'expectativas-realistas', 'Qué se puede afirmar y qué no, tres ideas que circulan sin comprobar y cuánto tarda en saberse algo.', 0, '<h3>🎯 Objetivo de la lección</h3><p>Poner sobre la mesa qué se puede esperar razonablemente de esta actividad, con lo que se puede afirmar y sin lo que no. Y deshacer tres ideas que circulan tanto que se dan por ciertas sin comprobarlas.</p><hr><h3>📏 Lo que se puede afirmar</h3><p>Muy poco, y conviene ser explícito sobre por qué.</p><p>Nadie puede decirte cuánto vas a ganar o perder, porque depende de decisiones que aún no has tomado, de un mercado que nadie predice y de una parte de azar. Cualquier cifra concreta que te den sobre tu resultado futuro está inventada, por bien intencionada que sea.</p><p>Lo que sí se puede afirmar, porque se deduce de las lecciones anteriores:</p><ul><li><p><strong>El resultado medio no puede ser positivo.</strong> El dinero sale de otro participante y hay costes por el camino. Es aritmética, no pesimismo.</p></li><li><p><strong>Los resultados no se reparten de forma pareja.</strong> Lo habitual es mucha gente perdiendo poco a poco y unos pocos ganando bastante.</p></li><li><p><strong>El tiempo necesario para saber si se te da bien es largo.</strong> Con pocas operaciones no se distingue habilidad de suerte.</p></li><li><p><strong>Los costes son seguros y el resultado no.</strong> Las comisiones se pagan siempre; el beneficio, no.</p></li></ul><p>No es mucho, pero es comprobable. El resto de lo que se cuenta sobre expectativas suele ser una cifra sin origen.</p><hr><h3>🔍 Tres ideas que conviene mirar de cerca</h3><p><strong>«El 90 % pierde dinero.»</strong> La cifra circula en todas las versiones, del 70 % al 95 %, y casi siempre sin fuente. Hay datos reales: los intermediarios que ofrecen contratos por diferencias en Europa están obligados a publicar qué porcentaje de sus clientes pierde dinero, y las cifras publicadas suelen situarse entre el 70 % y el 85 %. Es un dato acotado —solo ese producto, solo esos clientes— pero está publicado y se puede comprobar. Lo que no existe es una cifra única y global.</p><p><strong>«Con formación se cambia el resultado.»</strong> Formarse ayuda a no cometer errores evitables, y eso es real. Lo que no hace es cambiar de dónde sale el dinero ni quién está al otro lado. <strong>Es condición necesaria y no suficiente</strong>, y presentarla como la diferencia entre ganar y perder es lo que vende la mayoría de los cursos de pago.</p><p><strong>«Es una fuente de ingresos.»</strong> Un ingreso es algo previsible que llega con regularidad. Esto no lo es: el resultado varía, puede ser negativo durante periodos largos y no responde al esfuerzo de forma proporcional. <strong>Llamarlo ingreso cambia cómo se planifica una vida alrededor</strong>, y ahí está el daño real de esa idea.</p><hr><h3>⏳ Cuánto tarda en saberse algo</h3><p>Una expectativa concreta y poco cómoda.</p><p>Como una parte del resultado es azar, para distinguir si tu forma de operar produce algo hacen falta <strong>muchas operaciones a lo largo de mucho tiempo</strong>. No veinte, no un mes bueno. Y durante todo ese periodo estás pagando costes reales por averiguarlo.</p><p>Dicho de otro modo: <strong>el periodo de aprendizaje tiene un precio, se paga por adelantado y no garantiza el resultado</strong>. Es exactamente igual que en otras actividades competitivas; lo que cambia es que aquí el precio se paga en dinero propio.</p><p>Quien te presente una curva de aprendizaje de unas semanas está describiendo otra cosa.</p><hr><h3>🎯 Qué expectativa es razonable</h3><p>Si después de todo lo anterior decides seguir, lo que se puede esperar con fundamento es esto:</p><ul><li><p><strong>Que pierdas dinero al principio.</strong> No como fracaso, sino como el coste previsible de aprender en un entorno con costes.</p></li><li><p><strong>Que el resultado sea irregular.</strong> Periodos buenos y malos sin relación clara con lo bien o mal que lo estés haciendo.</p></li><li><p><strong>Que ocupe más tiempo del previsto.</strong> Siempre lo hace.</p></li><li><p><strong>Que no sepas si se te da bien durante bastante tiempo.</strong> Y que la tentación de concluirlo antes sea fuerte.</p></li></ul><p>Y una expectativa que conviene fijar por adelantado: <strong>decidir qué cantidad estás dispuesto a perder entera antes de empezar</strong>, entendiendo «perder entera» de forma literal. No como objetivo de gestión, sino como respuesta a una pregunta: si esto desaparece del todo, ¿cambia algo importante en mi vida? Si la respuesta es sí, la cantidad no es esa.</p><hr><h3>🧾 Cómo saber cómo te va de verdad</h3><p>Retomando lo de la lección 2.1, porque es donde más se engaña uno solo:</p><p><strong>Cuenta el dinero que metiste y el que sacaste.</strong> Todo, en un periodo largo, con comisiones y conversiones incluidas. Compáralo con lo que tendrías si no hubieras hecho nada, y con las horas que le dedicaste.</p><p>Es incómodo precisamente porque no se puede maquillar, y por eso es la única medida que sirve para decidir si seguir.</p><hr><h3>📌 En resumen</h3><ul><li><p>Casi nada se puede afirmar sobre tu resultado. Sí que <strong>el resultado medio no puede ser positivo</strong>, que los resultados no se reparten de forma pareja y que <strong>los costes son seguros y el beneficio no</strong>.</p></li><li><p>El «90 % pierde» circula sin fuente. Lo comprobable: los intermediarios europeos de contratos por diferencias <strong>publican por obligación</strong> sus porcentajes, habitualmente entre el 70 % y el 85 %.</p></li><li><p>La formación es <strong>necesaria y no suficiente</strong>: no cambia de dónde sale el dinero ni quién está al otro lado.</p></li><li><p>No es un ingreso, porque no es previsible ni regular. <strong>Llamarlo así cambia cómo se planifica una vida.</strong></p></li><li><p>El aprendizaje <strong>se paga por adelantado, en dinero propio, y no garantiza resultado</strong>.</p></li><li><p>La cantidad correcta es aquella que, si desaparece entera, <strong>no cambia nada importante</strong>.</p></li></ul><hr><h3>➡️ Qué viene después</h3><p>Queda una consecuencia que sorprende a mucha gente y que aparece gane o pierda: <strong>las obligaciones fiscales</strong>. Qué son, por qué pueden existir aunque el año haya sido malo, y por qué dependen de dónde vivas.</p>')
ON CONFLICT (id) DO UPDATE SET module_id = EXCLUDED.module_id, title = EXCLUDED.title,
  slug = EXCLUDED.slug, description = EXCLUDED.description, order_index = EXCLUDED.order_index,
  content = EXCLUDED.content;

-- 3.2 impuestos-y-obligaciones  (NUEVA)
INSERT INTO public.lessons (id, course_id, module_id, title, slug, description, order_index, content)
VALUES ('adf815b0-334b-4f11-bad6-458f25678e7f', '7efb8a11-7120-4e7f-9b49-20ed29b157e5', 'ac33c06e-442a-4756-ac74-b8a86ca634f8', 'Impuestos y obligaciones', 'impuestos-y-obligaciones', 'Por qué puede haber que pagar en un año malo, el problema del registro y las preguntas que llevar.', 1, '<h3>🎯 Objetivo de la lección</h3><p>Saber que operar genera obligaciones fiscales, entender por qué pueden aparecer aunque el año haya sido malo, y tener claro que las reglas concretas dependen del país. No para saber cuánto pagas —eso no se decide aquí—, sino para que la pieza esté sobre la mesa antes de decidir.</p><hr><h3>⚠️ Qué es esta lección y qué no</h3><p>Conviene delimitarlo antes de nada.</p><p><strong>Esto no es asesoramiento fiscal.</strong> No dice qué tienes que declarar, ni cuánto, ni cómo. Las normas cambian según el país, cambian con el tiempo y dependen de circunstancias personales que este curso no conoce.</p><p><strong>Lo que sí hace</strong> es explicar los mecanismos generales que hacen que esto sorprenda a tanta gente, y darte las preguntas que llevar a quien sí pueda responderlas. Porque el problema habitual no es pagar de más: es <strong>enterarse tarde</strong>.</p><hr><h3>🧾 Operar suele generar un hecho declarable</h3><p>La idea de partida, en casi todos los sistemas fiscales del mundo:</p><p><strong>Cada vez que vendes o intercambias, se calcula si hubo ganancia o pérdida respecto a lo que te costó.</strong> Ese cálculo es un hecho con consecuencias fiscales, con independencia de si sacaste el dinero a tu cuenta bancaria o no.</p><p>De ahí salen dos consecuencias que sorprenden a casi todo el mundo:</p><ul><li><p><strong>Cambiar una criptomoneda por otra suele contar.</strong> Mucha gente da por hecho que solo cuenta al convertir a euros. En bastantes países no es así: el intercambio entre dos activos ya es una venta y una compra.</p></li><li><p><strong>No hace falta retirar nada.</strong> El dinero puede seguir dentro de la plataforma y la obligación haber nacido igual.</p></li></ul><p>Junta esto con el trading, que consiste precisamente en operar muchas veces, y el resultado es previsible: <strong>quien opera a menudo puede generar cientos o miles de hechos declarables en un año</strong> sin haber movido un euro a su banco.</p><hr><h3>💥 Por qué puede haber que pagar en un año malo</h3><p>Esta es la parte que más disgustos causa, y merece un ejemplo.</p><p>Imagina que durante el año haces muchas operaciones y acumulas ganancias. Luego, cerca del final del año o al principio del siguiente, pierdes buena parte de lo ganado.</p><p>Según cómo funcione la norma de tu país, puede ocurrir que <strong>las ganancias del periodo tributen y las pérdidas posteriores no las compensen</strong>, o solo lo hagan parcialmente, o solo contra cierto tipo de rentas, o trasladándolas a años siguientes con límites.</p><p>El resultado en esos casos: una obligación fiscal calculada sobre un beneficio que ya no tienes. <strong>El calendario fiscal y el calendario del mercado no están sincronizados</strong>, y esa desincronización es el mecanismo del problema.</p><p>No pasa en todos los sistemas ni en todas las situaciones. Pasa lo suficiente como para que haya que preguntarlo antes, no después.</p><hr><h3>📚 El problema del registro</h3><p>Una dificultad práctica que casi nadie prevé y que crece con el tiempo.</p><p>Para calcular una ganancia hace falta saber <strong>qué te costó exactamente lo que vendiste</strong>. Con diez operaciones al año es llevadero. Con varios miles, repartidas entre plataformas distintas, con cambios entre activos por medio y con movimientos entre carteras propias, reconstruirlo a posteriori es muy trabajoso.</p><p>Y hay un detalle que lo complica: cuando has comprado lo mismo varias veces a precios distintos, hay que decidir qué unidades se consideran vendidas. Cada país tiene su regla, y la regla cambia el resultado.</p><p>De ahí lo único operativo que sí se puede recomendar sin entrar en terreno fiscal: <strong>guardar el historial desde el primer día</strong>. Exportarlo periódicamente de cada plataforma y conservarlo. No porque lo vayas a necesitar seguro, sino porque reconstruirlo después es mucho peor que guardarlo ahora, y las plataformas cierran, cambian de manos o limitan cuánto historial te dejan descargar.</p><hr><h3>🌍 Por qué depende del país</h3><p>Las diferencias entre jurisdicciones no son de matiz. Entre países varía:</p><ul><li><p><strong>Si el intercambio entre activos genera obligación</strong> o solo la conversión a moneda tradicional.</p></li><li><p><strong>Qué tipo de renta es</strong> y a qué tipo tributa, que puede depender de la frecuencia con que operes.</p></li><li><p><strong>Cómo se compensan las pérdidas</strong> con las ganancias, dentro del año y entre años.</p></li><li><p><strong>Qué regla se aplica</strong> para decidir qué unidades vendiste.</p></li><li><p><strong>Qué obligaciones de información</strong> existen, que pueden ser independientes de si hay algo que pagar.</p></li></ul><p>Y hay un factor que crece: cada vez más plataformas están obligadas a informar a las administraciones sobre sus usuarios. <strong>La pregunta práctica ya no es si se sabrá, sino si tú llevas la cuenta igual de bien que quien la recibe.</strong></p><hr><h3>❓ Las preguntas que llevar</h3><p>Lo útil de esta lección, en forma de lista para quien sí pueda responder:</p><ol><li><p>¿En mi país, cambiar un activo por otro genera obligación, o solo la venta a moneda tradicional?</p></li><li><p>¿Cómo se compensan las pérdidas con las ganancias, dentro del año y con años siguientes?</p></li><li><p>¿Cambia algo si opero mucho, o si uso productos apalancados?</p></li><li><p>¿Qué regla se aplica para decidir qué unidades he vendido?</p></li><li><p>¿Hay obligaciones de informar aunque no haya nada que pagar?</p></li><li><p>¿Qué documentación tengo que conservar, y cuánto tiempo?</p></li></ol><p>Con esas seis respuestas, obtenidas <strong>antes</strong> de empezar y no en la primera declaración, la sorpresa desaparece. Que es todo lo que pretende esta lección.</p><hr><h3>📌 En resumen</h3><ul><li><p>Esto <strong>no es asesoramiento fiscal</strong>: es saber que la pieza existe y qué preguntar a quien pueda responderla.</p></li><li><p>Cada venta o intercambio suele generar un hecho declarable, <strong>aunque no retires nada a tu banco</strong>. En bastantes países, cambiar un activo por otro ya cuenta.</p></li><li><p>Operar a menudo puede producir <strong>cientos o miles de hechos declarables al año</strong>.</p></li><li><p><strong>El calendario fiscal y el del mercado no están sincronizados</strong>: puede haber obligación calculada sobre un beneficio que ya no tienes.</p></li><li><p>Reconstruir el historial a posteriori es muy trabajoso. <strong>Guárdalo desde el primer día</strong>: las plataformas cierran y limitan las descargas.</p></li><li><p>Todo depende del país, y cada vez más plataformas informan a las administraciones. <strong>La pregunta no es si se sabrá, sino si llevas la cuenta igual de bien.</strong></p></li></ul><hr><h3>➡️ Qué viene después</h3><p>Ya tienes todas las piezas: qué es, de dónde sale el dinero, qué cuesta, qué hace la cabeza, qué esperar y qué obligaciones aparecen. La última lección vuelve a la pregunta del principio: <strong>¿debería hacer trading?</strong></p>')
ON CONFLICT (id) DO UPDATE SET module_id = EXCLUDED.module_id, title = EXCLUDED.title,
  slug = EXCLUDED.slug, description = EXCLUDED.description, order_index = EXCLUDED.order_index,
  content = EXCLUDED.content;

-- 3.3 deberia-hacer-trading
INSERT INTO public.lessons (id, course_id, module_id, title, slug, description, order_index, content)
VALUES ('42939961-fb40-4ca9-8db3-2351e8e35b32', '7efb8a11-7120-4e7f-9b49-20ed29b157e5', 'ac33c06e-442a-4756-ac74-b8a86ca634f8', '¿Debería hacer trading?', 'deberia-hacer-trading', 'Qué querías conseguir, cuándo tiene sentido planteárselo, cuándo conviene esperar y qué hacer con cada respuesta.', 2, '<h3>🎯 Objetivo de la lección</h3><p>Volver a la pregunta del principio con todo lo visto encima de la mesa. No para responderla —eso no lo hace este curso— sino para que la respuesta la tomes tú con la información completa, incluida la posibilidad de que lo que buscabas fuera otra cosa.</p><hr><h3>🧾 Lo que sabes ahora y no sabías</h3><p>Siete cosas, puestas juntas porque juntas es como hay que decidir:</p><ul><li><p><strong>Es aprovechar movimientos de precio a corto plazo</strong>, y exige atención sostenida. No se hace distraído.</p></li><li><p><strong>El dinero sale de otro participante</strong>, y al otro lado suele haber profesionales con más medios y menos costes.</p></li><li><p><strong>El resultado medio no puede ser positivo.</strong> Es aritmética.</p></li><li><p><strong>Cada operación empieza en negativo</strong> por comisión, horquilla y deslizamiento. El punto de equilibrio no está en acertar la mitad de las veces.</p></li><li><p><strong>El apalancamiento no cambia la probabilidad, cambia cuánto margen tienes</strong> antes de perderlo todo.</p></li><li><p><strong>Saber todo esto no desactiva lo que hace la cabeza</strong> cuando hay dinero propio delante.</p></li><li><p><strong>Hay obligaciones fiscales</strong> que pueden aparecer aunque el año haya sido malo.</p></li></ul><p>Ninguna de las siete dice que no lo hagas. Todas dicen que, si lo haces, sepas dónde te metes.</p><hr><h3>🎯 Qué querías conseguir</h3><p>La pregunta más útil de toda la lección, porque en bastantes casos revela que la herramienta no era esta.</p><p><strong>Si lo que buscabas era ingresos regulares</strong>, esto no los produce. No es previsible ni responde al esfuerzo de forma proporcional. Puede dar resultado y no da regularidad.</p><p><strong>Si lo que buscabas era exposición a lo que ocurra en años</strong>, operar añade decisiones, costes y desgaste que no hacen falta para eso. Mantener hace justo eso sin nada de lo demás.</p><p><strong>Si lo que buscabas era resolver una situación apurada</strong>, conviene decirlo sin rodeos: es el peor punto de partida posible. La prisa empeora todas las conductas de la lección 2.3, y el apalancamiento —que es lo que aparenta resolver la falta de capital— es lo que acorta el plazo hasta perderlo.</p><p><strong>Si lo que buscabas era usar criptomonedas sin intermediarios</strong>, eso es otra actividad y está en <em>Uso práctico de Bitcoin</em>.</p><p><strong>Si lo que te atrae es el juego en sí</strong> —la decisión, el riesgo, el resultado inmediato—, eso es legítimo y conviene llamarlo por su nombre, porque cambia qué cantidad es razonable arriesgar y cómo medir si va bien.</p><hr><h3>✅ Cuándo tiene sentido planteárselo</h3><p>Sin decir que sí ni que no, hay condiciones que conviene que se cumplan a la vez. Si falta alguna, conviene esperar.</p><ul><li><p><strong>Que la cantidad pueda desaparecer entera sin cambiar nada importante</strong> en tu vida. Literalmente entera.</p></li><li><p><strong>Que tengas el tiempo</strong> que exige, de forma sostenida y no a ratos robados.</p></li><li><p><strong>Que no dependas del resultado</strong> para nada concreto, ni en fecha ni en cantidad.</p></li><li><p><strong>Que te interese la actividad</strong>, no solo lo que crees que produce. Es la que más se salta y la que más determina si aguantarás el tiempo que hace falta.</p></li><li><p><strong>Que hayas resuelto lo básico antes</strong>: custodia, seguridad y manejo. Operar con lo de debajo sin resolver añade un riesgo que no tiene que ver con el mercado.</p></li></ul><hr><h3>🚩 Cuándo conviene esperar</h3><p>Y la otra columna, dicha con la misma claridad:</p><ul><li><p>Si el dinero es <strong>prestado, o hace falta para otra cosa</strong>.</p></li><li><p>Si estás <strong>intentando recuperar</strong> una pérdida anterior, de esto o de cualquier otra cosa.</p></li><li><p>Si lo que te ha traído aquí es <strong>alguien que te lo propuso</strong>, sobre todo si insiste o si gana algo con que entres.</p></li><li><p>Si <strong>no puedes explicar con tus palabras</strong> de dónde saldría tu beneficio. Es la comprobación de la lección 1.3 y la más fiable de todas.</p></li><li><p>Si estás en un <strong>mal momento personal</strong>. El resultado inmediato y constante no ayuda a nadie que ya lo esté pasando mal.</p></li></ul><hr><h3>🪜 Si decides que sí</h3><p>Este curso no enseña a operar y no va a empezar ahora. Pero sí puede decir tres cosas sobre cómo seguir, que son de criterio y no de técnica:</p><p><strong>Aprende la parte operativa sabiendo qué buscas.</strong> Con lo visto aquí puedes evaluar un curso o un material: si promete rentabilidad, si evita hablar de costes, si presenta el apalancamiento por lo que multiplica sin decir lo que quita, ya sabes qué tipo de material es.</p><p><strong>Desconfía de quien cobre por enseñarte y no opere.</strong> No es descalificador por sí solo, pero es una pregunta razonable, y la respuesta dice mucho.</p><p><strong>Mide como en la lección 2.1.</strong> Dinero que entró menos dinero que salió, en un periodo largo, contra las horas dedicadas. Es lo único que no se puede maquillar, y es lo que te dirá si seguir.</p><hr><h3>🤝 Si decides que no</h3><p>También es un resultado del curso, y conviene decirlo sin condescendencia: <strong>decidir que esto no es para ti no es renunciar a nada</strong>. Es haber respondido a la pregunta con la que empezaste, que era el objetivo.</p><p>Nada de lo que has aprendido se desperdicia. Entender de dónde sale el dinero, cómo funcionan los costes y qué hace la cabeza bajo presión sirve para reconocer una propuesta dudosa, para leer lo que te cuenten y para no confundir actividades distintas.</p><p>Y si lo que quieres es seguir con criptomonedas por otro camino, los cursos de <em>Uso práctico de Bitcoin</em> y <em>Seguridad básica en Bitcoin y criptomonedas</em> cubren el uso y la custodia, que es donde se juega la mayor parte de lo que la gente pierde de verdad.</p><hr><h3>📌 En resumen</h3><ul><li><p>Siete cosas que ahora sabes, y juntas es como hay que decidir. <strong>Ninguna dice que no lo hagas</strong>; todas dicen que sepas dónde te metes.</p></li><li><p>La pregunta más útil es <strong>qué querías conseguir</strong>: ingresos regulares, exposición a años, resolver un apuro o usar criptomonedas son cuatro cosas, y para tres de ellas la herramienta es otra.</p></li><li><p>Tiene sentido planteárselo si <strong>la cantidad puede desaparecer entera</strong>, tienes el tiempo, no dependes del resultado, te interesa la actividad y lo básico está resuelto.</p></li><li><p>Conviene esperar si el dinero es prestado, si intentas recuperar, si te lo propuso alguien, si estás en un mal momento, o <strong>si no puedes explicar de dónde saldría tu beneficio</strong>.</p></li><li><p>Si sigues: evalúa el material con lo aprendido, pregunta a quien cobra por enseñar si opera, y <strong>mide por dinero que entró menos dinero que salió</strong>.</p></li><li><p><strong>Decidir que no es un resultado del curso</strong>, no una renuncia.</p></li></ul>')
ON CONFLICT (id) DO UPDATE SET module_id = EXCLUDED.module_id, title = EXCLUDED.title,
  slug = EXCLUDED.slug, description = EXCLUDED.description, order_index = EXCLUDED.order_index,
  content = EXCLUDED.content;

DELETE FROM public.quiz_questions WHERE module_id IN ('67f337df-bb2c-47fb-b58a-ef93e922746f', '91a8bd69-3c05-4b92-94aa-5025ffa77814', 'ac33c06e-442a-4756-ac74-b8a86ca634f8');

-- quiz M1
INSERT INTO public.quiz_questions (module_id, question, explanation, options, correct_answer, order_index, difficulty, points)
VALUES ('67f337df-bb2c-47fb-b58a-ef93e922746f', '¿Qué hace este curso y qué no hace?', 'No enseña a operar a propósito: cuándo entrar, qué parte del capital arriesgar o qué estrategia seguir depende de tu situación, y quien no te conoce no puede decidirlo por ti. Lo que hace es responder a qué es esta actividad y por qué casi nadie gana.', '["Enseña una estrategia sencilla para principiantes","Responde a qué es el trading y por qué casi nadie gana, pero no enseña a operar","Enseña a operar con poco riesgo","Compara plataformas para elegir la mejor"]'::jsonb, 1, 1, 'medium', 1);
INSERT INTO public.quiz_questions (module_id, question, explanation, options, correct_answer, order_index, difficulty, points)
VALUES ('67f337df-bb2c-47fb-b58a-ef93e922746f', '¿Qué define exactamente al trading frente a otras formas de tener un activo?', 'Las dos mitades importan: el objetivo es el movimiento del precio, no el uso de lo comprado ni lo que valga en diez años, y el plazo es corto. Si el plazo se alarga lo suficiente, deja de ser esto.', '["Que se hace con criptomonedas y no con acciones","Que busca el movimiento del precio en plazos cortos","Que se hace con dinero prestado","Que requiere análisis de gráficos"]'::jsonb, 1, 2, 'medium', 1);
INSERT INTO public.quiz_questions (module_id, question, explanation, options, correct_answer, order_index, difficulty, points)
VALUES ('67f337df-bb2c-47fb-b58a-ef93e922746f', 'En trading, ¿qué relación hay entre acertar y decidir bien?', 'Se puede tomar una decisión razonable y perder dinero, y una pésima y ganarlo. Con pocas operaciones no hay forma de distinguirlo. Es lo contrario de casi cualquier otra actividad, donde hacerlo bien y que salga bien van de la mano.', '["Son lo mismo: si aciertas es que decidiste bien","Son cosas distintas, y con pocas operaciones no se pueden separar","Decidir bien garantiza acertar a largo plazo","Acertar depende solo de la formación"]'::jsonb, 1, 3, 'medium', 1);
INSERT INTO public.quiz_questions (module_id, question, explanation, options, correct_answer, order_index, difficulty, points)
VALUES ('67f337df-bb2c-47fb-b58a-ef93e922746f', 'Usar, mantener y operar criptomonedas son tres actividades. ¿Qué dice este curso sobre cuál conviene?', 'Son actividades distintas, con exigencias y riesgos distintos. El curso las compara por lo comprobable —qué exige cada una, en qué plazo se ve el resultado y qué tiene que pasar para perder— y no afirma cuál conviene, porque eso depende de cada persona.', '["Que mantener es lo más sensato para la mayoría","Que operar es la más rentable si hay formación","Que no dice cuál conviene: depende de cada persona","Que usar es la única sin riesgo"]'::jsonb, 2, 4, 'medium', 1);
INSERT INTO public.quiz_questions (module_id, question, explanation, options, correct_answer, order_index, difficulty, points)
VALUES ('67f337df-bb2c-47fb-b58a-ef93e922746f', 'Sobre mantener un activo durante años, ¿qué se puede afirmar?', 'Nadie puede afirmar que funcione. Puede salir bien o mal, y que haya salido bien antes no dice qué hará después. Lo único describible es lo que exige —resolver la custodia y no actuar—, no lo que produce.', '["Que históricamente ha funcionado, así que es la opción prudente","Que el tiempo juega a favor de quien espera","Que no se puede afirmar que funcione: solo se puede describir lo que exige","Que es preferible a operar en todos los casos"]'::jsonb, 2, 5, 'medium', 1);
INSERT INTO public.quiz_questions (module_id, question, explanation, options, correct_answer, order_index, difficulty, points)
VALUES ('67f337df-bb2c-47fb-b58a-ef93e922746f', 'Cuando alguien gana dinero operando, ¿de dónde sale ese dinero?', 'No lo crea el mercado ni aparece por el movimiento del precio: sale del bolsillo de otro participante. Saber de quién y en qué condiciones dice más sobre esta actividad que cualquier explicación de gráficos.', '["Del crecimiento del mercado en su conjunto","Del bolsillo de otro participante","De las comisiones que cobran las plataformas","De la emisión de nuevas unidades"]'::jsonb, 1, 6, 'medium', 1);
INSERT INTO public.quiz_questions (module_id, question, explanation, options, correct_answer, order_index, difficulty, points)
VALUES ('67f337df-bb2c-47fb-b58a-ef93e922746f', 'En futuros y contratos por diferencias, ¿cuál es la suma de lo que ganan y pierden todos los participantes?', 'De cada euro que gana un lado, ese euro lo pone el otro. Y como además hay costes, la suma de todos es menor que cero: entre todos pierden lo que se llevan las comisiones. No es una opinión sobre el instrumento: es cómo está construido.', '["Positiva, porque el mercado crece con el tiempo","Cero exacto","Menor que cero, porque los costes salen de los participantes","Depende de la dirección del precio"]'::jsonb, 2, 7, 'medium', 1);
INSERT INTO public.quiz_questions (module_id, question, explanation, options, correct_answer, order_index, difficulty, points)
VALUES ('67f337df-bb2c-47fb-b58a-ef93e922746f', '¿Quién suele estar al otro lado de tus operaciones?', 'Buena parte del volumen lo mueven empresas dedicadas exclusivamente a esto, con sistemas automáticos, mejores datos y costes por operación mucho más bajos. No hacen trampas: hacen la misma actividad con más medios y a tiempo completo.', '["Otros particulares en tu misma situación","Participantes profesionales con sistemas automáticos y costes más bajos","La propia plataforma, que apuesta contra ti","Nadie: las órdenes las casa un algoritmo neutral"]'::jsonb, 1, 8, 'medium', 1);
INSERT INTO public.quiz_questions (module_id, question, explanation, options, correct_answer, order_index, difficulty, points)
VALUES ('67f337df-bb2c-47fb-b58a-ef93e922746f', '¿Por qué no puede ser que la mayoría de quienes operan gane dinero?', 'Si lo que gana un lado lo pone el otro y además hay un coste fijo por participar, es aritmética, no mala suerte. La distribución habitual es muchos perdiendo poco a poco y unos pocos ganando bastante.', '["Porque la mayoría no se forma lo suficiente","Porque el mercado está manipulado","Por aritmética: el dinero sale de otro participante y hay costes por el camino","Porque las plataformas lo impiden"]'::jsonb, 2, 9, 'medium', 1);

-- quiz M2
INSERT INTO public.quiz_questions (module_id, question, explanation, options, correct_answer, order_index, difficulty, points)
VALUES ('91a8bd69-3c05-4b92-94aa-5025ffa77814', 'La comisión por operar parece pequeña. ¿Qué la convierte en el gasto principal?', 'La frecuencia. Un coste pequeño aplicado muchas veces se convierte en el gasto principal de la actividad, y se cobra igual si acertaste que si no. Operar más no es esforzarse más.', '["Que sube cuando el mercado se mueve mucho","La frecuencia: se cobra en cada entrada y en cada salida","Que se cobra sobre el beneficio obtenido","Que es distinta en cada plataforma"]'::jsonb, 1, 1, 'medium', 1);
INSERT INTO public.quiz_questions (module_id, question, explanation, options, correct_answer, order_index, difficulty, points)
VALUES ('91a8bd69-3c05-4b92-94aa-5025ffa77814', '¿Qué es la horquilla y qué implica?', 'En cualquier mercado hay dos precios a la vez: uno al que puedes comprar ya y otro algo más bajo al que puedes vender ya. Implica que en el instante de abrir una posición ya estás perdiendo, aunque el precio no se haya movido.', '["La comisión que cobra la plataforma por operar","La diferencia entre el precio de compra y el de venta, que te hace empezar perdiendo","El impuesto que se aplica a cada operación","La variación del precio durante el día"]'::jsonb, 1, 2, 'medium', 1);
INSERT INTO public.quiz_questions (module_id, question, explanation, options, correct_answer, order_index, difficulty, points)
VALUES ('91a8bd69-3c05-4b92-94aa-5025ffa77814', 'Un mercado con poca liquidez, ¿cómo se comporta?', 'Con poca actividad la horquilla se ensancha y el deslizamiento crece. Es cómodo para entrar y caro para salir, y eso no se nota hasta el día en que quieres salir. Además el deslizamiento empeora justo en los momentos de pánico.', '["Es más seguro porque hay menos movimiento","Cómodo para entrar y caro para salir, y no se nota hasta que quieres salir","Igual que uno líquido, solo que con menos volumen","Es mejor para operaciones grandes"]'::jsonb, 1, 3, 'medium', 1);
INSERT INTO public.quiz_questions (module_id, question, explanation, options, correct_answer, order_index, difficulty, points)
VALUES ('91a8bd69-3c05-4b92-94aa-5025ffa77814', '¿Dónde está el punto a partir del cual operar produce resultado positivo?', 'No en acertar la mitad de las veces: más arriba. Con comisión en cada entrada y salida, más horquilla, más deslizamiento, cada operación empieza en negativo, y el movimiento del precio tiene que cubrir todo eso antes de producir nada.', '["En acertar más de la mitad de las operaciones","Más arriba de la mitad, porque cada operación empieza en negativo","En acertar una de cada tres, si las ganancias son grandes","Depende solo de la estrategia elegida"]'::jsonb, 1, 4, 'medium', 1);
INSERT INTO public.quiz_questions (module_id, question, explanation, options, correct_answer, order_index, difficulty, points)
VALUES ('91a8bd69-3c05-4b92-94aa-5025ffa77814', '¿Cuál es la única forma de medir tu resultado que no se puede maquillar?', 'Dinero que entró menos dinero que salió, en un periodo largo, con comisiones y conversiones incluidas. El recuento operación a operación permite recordar las buenas; el porcentaje permite elegir desde cuándo se mide; comparar con el máximo permite sentirse bien con una pérdida.', '["El porcentaje de operaciones acertadas","La rentabilidad porcentual del último trimestre","Dinero que metiste frente a dinero que sacaste, en un periodo largo","La comparación con el mejor momento de tu cuenta"]'::jsonb, 2, 5, 'medium', 1);
INSERT INTO public.quiz_questions (module_id, question, explanation, options, correct_answer, order_index, difficulty, points)
VALUES ('91a8bd69-3c05-4b92-94aa-5025ffa77814', '¿Qué hace exactamente el apalancamiento?', 'Operar con una cantidad mayor de la que has puesto. Multiplica el movimiento del precio en los dos sentidos por igual: es una multiplicación, no una trampa ni un producto de riesgo por sí mismo. Lo que cambia su naturaleza es la liquidación.', '["Aumenta la probabilidad de que el precio vaya a tu favor","Multiplica el movimiento del precio en los dos sentidos por igual","Reduce las comisiones al operar más volumen","Protege contra las caídas bruscas"]'::jsonb, 1, 6, 'medium', 1);
INSERT INTO public.quiz_questions (module_id, question, explanation, options, correct_answer, order_index, difficulty, points)
VALUES ('91a8bd69-3c05-4b92-94aa-5025ffa77814', 'Operas con un multiplicador de cien. ¿Qué movimiento del precio en tu contra basta para acabar con la posición?', 'El apalancamiento no aumenta la probabilidad de que el precio vaya en tu contra: reduce cuánto tiene que ir para que lo pierdas todo. Con diez veces, un 10 %; con veinte, un 5 %; con cien, un 1 %. La liquidación no avisa, es definitiva y no espera a que el precio vuelva.', '["Un 10 %","Un 5 %","Un 1 %","Depende de la plataforma"]'::jsonb, 2, 7, 'medium', 1);
INSERT INTO public.quiz_questions (module_id, question, explanation, options, correct_answer, order_index, difficulty, points)
VALUES ('91a8bd69-3c05-4b92-94aa-5025ffa77814', 'Pierdes el 50 % de tu capital. ¿Cuánto tienes que ganar para volver al punto de partida?', 'Si tienes 100 y pierdes la mitad te quedan 50: para volver a 100 hace falta un 100 %. Cuanto más profunda la pérdida, peor la proporción —de un −80 % se sale con un +400 %—, y con apalancamiento se llega a esa zona con movimientos de precio pequeños.', '["Un 50 %","Un 75 %","Un 100 %","Un 150 %"]'::jsonb, 2, 8, 'medium', 1);
INSERT INTO public.quiz_questions (module_id, question, explanation, options, correct_answer, order_index, difficulty, points)
VALUES ('91a8bd69-3c05-4b92-94aa-5025ffa77814', '¿Por qué el patrón habitual es «muchas ganancias pequeñas y unas pocas pérdidas grandes»?', 'Perder pesa más que ganar la misma cantidad. Eso empuja a cerrar pronto lo que va bien, para asegurar la ganancia, y a aguantar lo que va mal, porque cerrarlo convierte una pérdida provisional en definitiva. Por eso se puede acertar la mayoría de las veces y perder igual.', '["Porque los mercados suben despacio y caen deprisa","Porque perder pesa más que ganar: se cierra pronto lo bueno y se aguanta lo malo","Porque las comisiones se cobran solo en las operaciones ganadoras","Porque los profesionales manipulan los precios"]'::jsonb, 1, 9, 'medium', 1);

-- quiz M3
INSERT INTO public.quiz_questions (module_id, question, explanation, options, correct_answer, order_index, difficulty, points)
VALUES ('ac33c06e-442a-4756-ac74-b8a86ca634f8', '¿Qué se puede afirmar con fundamento sobre tu resultado futuro operando?', 'Nada concreto: depende de decisiones que no has tomado, de un mercado que nadie predice y de una parte de azar. Sí se puede afirmar que el resultado medio no puede ser positivo, que los resultados no se reparten de forma pareja y que los costes son seguros mientras el beneficio no lo es.', '["Una rentabilidad media razonable si te formas bien","Nada concreto: cualquier cifra sobre tu resultado futuro está inventada","Que perderás dinero con seguridad","Que ganarás si dedicas suficientes horas"]'::jsonb, 1, 1, 'medium', 1);
INSERT INTO public.quiz_questions (module_id, question, explanation, options, correct_answer, order_index, difficulty, points)
VALUES ('ac33c06e-442a-4756-ac74-b8a86ca634f8', 'Sobre la cifra «el 90 % pierde dinero», ¿qué es lo comprobable?', 'La cifra circula en todas las versiones y casi siempre sin fuente. Lo que sí está publicado: los intermediarios que ofrecen contratos por diferencias en Europa están obligados a publicar qué porcentaje de sus clientes pierde, y suele situarse entre el 70 % y el 85 %. Es un dato acotado a ese producto, no una cifra global.', '["Que el 90 % es una cifra verificada por los reguladores","Que los intermediarios europeos de contratos por diferencias publican por obligación cifras del 70 % al 85 %","Que no existe ningún dato sobre esto","Que la cifra real es mucho menor"]'::jsonb, 1, 2, 'medium', 1);
INSERT INTO public.quiz_questions (module_id, question, explanation, options, correct_answer, order_index, difficulty, points)
VALUES ('ac33c06e-442a-4756-ac74-b8a86ca634f8', '¿Qué cambia la formación en trading?', 'Ayuda a no cometer errores evitables, y eso es real. Lo que no hace es cambiar de dónde sale el dinero ni quién está al otro lado: es condición necesaria y no suficiente. Presentarla como la diferencia entre ganar y perder es lo que vende la mayoría de los cursos de pago.', '["Es la diferencia entre ganar y perder","Es necesaria pero no suficiente: no cambia de dónde sale el dinero","No sirve de nada, porque todo es azar","Garantiza resultados a partir del primer año"]'::jsonb, 1, 3, 'medium', 1);
INSERT INTO public.quiz_questions (module_id, question, explanation, options, correct_answer, order_index, difficulty, points)
VALUES ('ac33c06e-442a-4756-ac74-b8a86ca634f8', '¿Por qué es problemático llamar «fuente de ingresos» al trading?', 'Un ingreso es algo previsible que llega con regularidad, y esto no lo es: varía, puede ser negativo durante periodos largos y no responde al esfuerzo de forma proporcional. El daño real de esa idea es que cambia cómo se planifica una vida alrededor.', '["Porque los ingresos tributan de forma distinta","Porque no es previsible ni regular, y llamarlo así cambia cómo se planifica una vida","Porque los ingresos requieren dedicación completa","Porque solo es ingreso si superas cierta cantidad"]'::jsonb, 1, 4, 'medium', 1);
INSERT INTO public.quiz_questions (module_id, question, explanation, options, correct_answer, order_index, difficulty, points)
VALUES ('ac33c06e-442a-4756-ac74-b8a86ca634f8', '¿Cuánto tarda en saberse si tu forma de operar produce algo?', 'Como parte del resultado es azar, hacen falta muchas operaciones a lo largo de mucho tiempo. No veinte, no un mes bueno. Y durante todo ese periodo estás pagando costes reales por averiguarlo: el aprendizaje se paga por adelantado y no garantiza resultado.', '["Unas semanas con práctica intensiva","Unos meses, si llevas un registro ordenado","Muchas operaciones a lo largo de mucho tiempo, pagando costes mientras tanto","Se sabe desde las primeras operaciones"]'::jsonb, 2, 5, 'medium', 1);
INSERT INTO public.quiz_questions (module_id, question, explanation, options, correct_answer, order_index, difficulty, points)
VALUES ('ac33c06e-442a-4756-ac74-b8a86ca634f8', 'Cambias una criptomoneda por otra sin retirar nada a tu banco. ¿Puede haber consecuencias fiscales?', 'En bastantes países el intercambio entre dos activos ya es una venta y una compra, y genera un hecho declarable aunque el dinero siga dentro de la plataforma. Quien opera a menudo puede producir cientos o miles de hechos declarables en un año sin mover un euro a su banco.', '["No: solo cuenta al convertir a euros","No, mientras el dinero no salga de la plataforma","Sí: en bastantes países el intercambio ya cuenta como venta","Solo si la cantidad supera cierto límite"]'::jsonb, 2, 6, 'medium', 1);
INSERT INTO public.quiz_questions (module_id, question, explanation, options, correct_answer, order_index, difficulty, points)
VALUES ('ac33c06e-442a-4756-ac74-b8a86ca634f8', '¿Cómo puede haber una obligación fiscal en un año que terminó en pérdidas?', 'El calendario fiscal y el del mercado no están sincronizados. Según la norma de cada país, las ganancias de un periodo pueden tributar sin que las pérdidas posteriores las compensen, o solo parcialmente, o trasladándolas a años siguientes con límites. El resultado: una obligación calculada sobre un beneficio que ya no tienes.', '["No es posible: si pierdes, no hay nada que declarar","Porque las ganancias de un periodo pueden tributar sin que las pérdidas posteriores las compensen del todo","Porque se tributa por el volumen operado, no por el resultado","Solo ocurre con productos apalancados"]'::jsonb, 1, 7, 'medium', 1);
INSERT INTO public.quiz_questions (module_id, question, explanation, options, correct_answer, order_index, difficulty, points)
VALUES ('ac33c06e-442a-4756-ac74-b8a86ca634f8', '¿Qué conviene hacer desde el primer día respecto al historial de operaciones?', 'Guardarlo y exportarlo periódicamente de cada plataforma. Reconstruirlo a posteriori con miles de operaciones repartidas entre plataformas es muy trabajoso, y las plataformas cierran, cambian de manos o limitan cuánto historial dejan descargar.', '["Nada: las plataformas lo conservan indefinidamente","Exportarlo y guardarlo periódicamente, porque reconstruirlo después es mucho peor","Anotar solo las operaciones con beneficio","Esperar a la primera declaración para pedirlo"]'::jsonb, 1, 8, 'medium', 1);
INSERT INTO public.quiz_questions (module_id, question, explanation, options, correct_answer, order_index, difficulty, points)
VALUES ('ac33c06e-442a-4756-ac74-b8a86ca634f8', '¿Cuál de estas situaciones es la señal más fiable de que conviene esperar antes de operar?', 'Es la comprobación de la lección sobre de dónde sale el dinero, y la más fiable de todas: si no puedes explicar con tus palabras de dónde saldría tu beneficio, falta lo esencial. Las otras tres también son motivos para esperar, pero esta es la que revela si has entendido la actividad.', '["Que el mercado esté en un momento volátil","Que no tengas todavía una estrategia definida","Que no puedas explicar con tus palabras de dónde saldría tu beneficio","Que la plataforma cobre comisiones altas"]'::jsonb, 2, 9, 'medium', 1);

-- ============================================================================
-- 4. Archivado de los dos cursos absorbidos
-- ============================================================================
-- Sus filas de learning_path_courses se conservan: RLS deja de servirlos a un
-- usuario normal, el embed devuelve NULL y la ruta no los muestra.

UPDATE public.courses SET status = 'archived' WHERE id = '68ab8b39-05ba-45f8-a9c2-10c38f4d6ad0';  -- ecosistema-web3-explicado

UPDATE public.courses SET status = 'archived' WHERE id = '87d24abe-2ada-40af-a7ed-60c0060ae4eb';  -- gestion-del-riesgo-y-mentalidad-en-trading

-- ============================================================================
-- 5. Devolver los dos cursos a 'published'
-- ============================================================================
-- Necesario solo si el disparador de la 030 llego a actuar. Con el SET LOCAL
-- de arriba no hace falta, y es inofensivo: filtra por el estado actual.

UPDATE public.courses SET status = 'published', updated_at = now()
 WHERE slug = 'introduccion-a-web3' AND status = 'pending_review';

UPDATE public.courses SET status = 'published', updated_at = now()
 WHERE slug = 'introduccion-al-trading-de-criptomonedas' AND status = 'pending_review';

-- ============================================================================
