-- congela lo que se completo entonces y el porcentaje refleja el presente.

UPDATE public.course_enrollments SET progress_percentage = 0
 WHERE id = 'fb742c0f-6b31-45a6-a006-b1663cf13ff2';  -- 34c7dd0a, introduccion-al-trading-de-criptomonedas

UPDATE public.course_enrollments SET progress_percentage = 67
