UPDATE public.course_enrollments SET progress_percentage = 56
 WHERE id = '06e6f0df-b878-46d2-9890-369c2f20ac7b';  -- 53027efc, introduccion-al-trading-de-criptomonedas

UPDATE public.course_enrollments SET progress_percentage = 67
 WHERE id = '980a4117-5c4d-49d8-b100-ba472a014320';  -- ad03ae2f, introduccion-al-trading-de-criptomonedas

UPDATE public.course_enrollments SET progress_percentage = 67
 WHERE id = 'c8056bf6-b553-429d-bc5e-4192cee3ffed';  -- ab354bca, introduccion-al-trading-de-criptomonedas

